(window.__BOOKS=window.__BOOKS||{})["e_hippolytus"]={"b":[["h2","Действующие лица"],["person","<span class=\"pn\"><span class=\"ch\" data-ch=\"afrodita\">Афродита</span></span> <span class=\"act-no\">(II)</span>"],["person","<span class=\"pn\">Ипполит, сын <span class=\"ch\" data-ch=\"tesey\">Тесея</span> от амазонки</span> <span class=\"act-no\">(I)</span>"],["person","<span class=\"pn\">Хор охотников-товарищей <span class=\"ch\" data-ch=\"ippolit\">Ипполита</span></span>"],["person","<span class=\"pn\">Старый раб</span> <span class=\"act-no\">(III)</span>"],["person","<span class=\"pn\">Хор трезенских женщин</span>"],["person","<span class=\"pn\"><span class=\"ch\" data-ch=\"kormilitsa\">Кормилица</span></span> <span class=\"act-no\">(III)</span>"],["person","<span class=\"pn\">Федра, жена <span class=\"ch\" data-ch=\"tesey\">Тесея</span></span> <span class=\"act-no\">(II)</span>"],["person","<span class=\"pn\">Тесей, царь афинский</span> <span class=\"act-no\">(II)</span>"],["person","<span class=\"pn\">Вестник</span> <span class=\"act-no\">(III)</span>"],["person","<span class=\"pn\"><span class=\"ch\" data-ch=\"artemida\">Артемида</span></span> <span class=\"act-no\">(III)</span>"],["person","<span class=\"pn\">Свита <span class=\"ch\" data-ch=\"ippolit\">Ипполита</span>, свита <span class=\"ch\" data-ch=\"tesey\">Тесея</span>, свита <span class=\"ch\" data-ch=\"fedra\">Федры</span></span>"],["place","Действие происходит в Трезене перед дворцом."],["act","Пролог","a1",""],["sd","Сцена представляет площадь, ограниченную фасадом царского дворца Питфея, в дорийском стиле (дворец занимает середину заднего плана). Перед порталом справа (от зрителей) стоит изваяние <span class=\"ch\" data-ch=\"artemida\">Артемиды</span>, слева — <span class=\"ch\" data-ch=\"afrodita\">Афродиты</span>. С боков к фасаду примыкают отдельные здания с особыми входами. Правая кулиса изображает город, а левая — деревню, между ними и задней стеной оставлены проходы — правый в город, левый за пределы страны."],["scene","Явление первое","s1",1,1],["sd","Раннее утро."],["sd","<span class=\"ch\" data-ch=\"afrodita\">Афродита</span> (появляясь на возвышении)"],["v","Полна земля молвой о нас, и ярок",0,1,0,0],["v","И в небесах <span class=\"ch\" data-ch=\"afrodita\">Киприды</span> дивной блеск,",0,1,0,0],["v","И сколько есть людей под солнцем дальним",0,2,0,0],["v","От Понта до Атлантовых пределов,",0,3,0,0],["v","Того, кто власть мою приемлет кротко,",0,4,0,0],["v","Лелею я, но если предо мной",0,5,0,0],["v","Гордиться кто задумает, тот гибнет.",0,6,0,0],["v","Таков уж род бессмертных, — что дары",0,7,0,0],["v","Из смертных рук сердцам отрадны нашим.",0,8,0,0],["v","И правду слов я скоро здесь явлю.",0,9,0,0],["v","Из всех один меня в Трезене этом<a class=\"nr\" href=\"#n-k1\" data-n=\"k1\" aria-label=\"Примечание 1\">1</a>",0,10,1,1],["v","Тесеев сын, надменный <span class=\"ch\" data-ch=\"ippolit\">Ипполит</span>,",0,10,0,0],["v","Могучею рожденный Амазонкой",0,11,0,0],["v","И благостным Питфеем воспоен,",0,12,0,0],["v","Последнею расславил в сонмах дивных.",0,13,0,0],["v","Он радостей и уз любви бежит,",0,14,0,0],["v","А меж богов сестры милее Феба",0,15,0,0],["v","И Зевсовой нет дочери ему…",0,15,0,0],["v","И с чистою среди зеленой чащи",0,16,0,0],["v","Не знает он разлуки. Своры он",0,17,0,0],["v","По зверю там гоняет с нею рядом,",0,18,0,0],["v","Сообществом божественным почтен…",0,19,0,0],["v","Нет зависти во мне: какое дело",0,20,0,1],["v","Мне до того? Но в чем передо мной",0,20,0,0],["v","Он погрешил, за то гордец ответит",0,21,0,0],["v","Сегодня же… Нависла и давно",0,22,0,0],["v","Лишь мига ждет, чтоб оборваться, кара.",0,23,0,0],["v","Когда чертог покинул он Питфея,",0,23,0,0],["v","Чтоб Элевсина таинства узреть,<a class=\"nr\" href=\"#n-k2\" data-n=\"k2\" aria-label=\"Примечание 2\">2</a>",0,24,0,0],["v","Священный град Афины посетил,",0,25,0,0],["v","Там юношу увидела жена",0,26,0,0],["v","Его отца, блистающая родом;",0,26,0,0],["v","И чарами Эрота сердце в ней",0,27,0,0],["v","В тот миг зажглось моей державной волей,",0,28,0,0],["v","И ранее, чем уезжать сюда,",0,29,0,0],["v","Влюбленная, она скалу Паллады",0,30,0,1],["v","С той стороны, что смотрит на Трезен,",0,30,0,0],["v","Святилищем украсила <span class=\"ch\" data-ch=\"afrodita\">Киприды</span>,",0,31,0,0],["v","И храм ее тоскующей любви",0,32,0,0],["v","Так и прослыл «святыней <span class=\"ch\" data-ch=\"ippolit\">Ипполита</span>».",0,33,0,0],["v","Когда ж <span class=\"ch\" data-ch=\"tesey\">Тесей</span>, чтобы себя омыть<a class=\"nr\" href=\"#n-k3\" data-n=\"k3\" aria-label=\"Примечание 3\">3</a>",0,33,1,0],["v","От пролитой им крови Паллантидов,",0,34,0,0],["v","В изгнание из Аттики с женой",0,35,0,0],["v","Сюда, в Трезен, свой парус направляет",0,36,0,0],["v","На целый год — несчастная, мечты",0,36,0,0],["v","Безумные со стонами мешая,",0,37,0,0],["v","Здесь от Эрота жала сохнуть стала.",0,38,0,0],["v","Она молчит. Из челяди никто",0,39,0,0],["v","О тайне и не знает. Только страсти",0,40,0,1],["v","Не суждено угаснуть без следа:",0,41,0,0],["v","Отцу о ней я расскажу, Тесею,",0,42,0,0],["v","И будет нам враждебный <span class=\"ch\" data-ch=\"ippolit\">Ипполит</span>",0,43,0,0],["v","Убит его проклятьем. Царь глубинный,",0,44,0,0],["v","Недаром же <span class=\"ch\" data-ch=\"tesey\">Тесею</span> Посейдон<a class=\"nr\" href=\"#n-k4\" data-n=\"k4\" aria-label=\"Примечание 4\">4</a>",0,45,0,0],["v","Три посулил желания исполнить.",0,46,0,0],["v","Прославлена — но все-таки умрет",0,47,0,0],["v","И <span class=\"ch\" data-ch=\"fedra\">Федра</span>. Пусть! Мне лучше, чтобы <span class=\"ch\" data-ch=\"fedra\">Федра</span>",0,48,0,0],["v","Погибла, чем, виновных поразив,",0,49,0,0],["v","Мне сердца, месть лаская, не насытить.",0,50,0,1],["sd","(Издали слышатся хоры товарищей <span class=\"ch\" data-ch=\"ippolit\">Ипполита</span>)"],["v","Но вот и он… <span class=\"ch\" data-ch=\"tesey\">Тесея</span> <span class=\"ch\" data-ch=\"ippolit\">Ипполит</span>,",0,50,0,0],["v","Надменный сын… Покинув лов тяжелый…",0,51,0,0],["v","Сюда идет — я ухожу…",0,52,0,0],["sd","(Спускается со своей эстрады.)"],["v","Пора.",0,53,4,0],["sd","(Всматривается.)"],["v","С какою он большой, веселой свитой.",0,53,0,0],["sd","(Прислушиваясь.)"],["v","Как ярко гимн их Девственной звучит,",0,54,0,0],["v","Богине их отраден, <span class=\"ch\" data-ch=\"artemida\">Артемиде</span>:",0,55,0,0],["v","Не чует он, что Адовы врата",0,56,0,0],["v","Уж для него открыты… и что солнца",0,56,0,0],["v","Последнего он пьет теперь лучи…",0,57,0,0],["sd","(Уходит налево.)"],["scene","Явление второе","s2",1,2],["sd","<span class=\"ch\" data-ch=\"ippolit\">Ипполит</span> со спутниками (справа); их 15 человек, они одеты в охотничьи костюмы и вооружены дротиками. <span class=\"ch\" data-ch=\"ippolit\">Ипполит</span> — юноша с локонами золотисто-белого цвета и строгим лицом; у него светлые голубые глаза, его одежда и приемы более говорят о палестре, охоте и играх, чем о войне и лагере. В руке у него венок из полевых цветов. При появлении <span class=\"ch\" data-ch=\"ippolit\">Ипполита</span> из дому выходит несколько рабов, в том числе и Старый раб. Шествие направляется к статуе <span class=\"ch\" data-ch=\"artemida\">Артемиды</span>."],["sp","<span class=\"ch\" data-ch=\"ippolit\">Ипполит</span>"],["v","О, восславьте гимном, други,",0,58,0,0],["v","Золотую Дия дочь,",0,59,0,0],["v","Артемиду, нашу радость!",0,60,0,1],["sd","Охотники (к статуе)"],["v","Дева-владычица,",0,60,2,0],["v","Радуйся, сильная",0,61,2,0],["v","Зевсова дочь!",0,62,2,0],["v","Чада Латоны нет",0,63,2,0],["v","В мире прекраснее.",0,63,2,0],["v","О Артемида, нам",0,64,2,0],["v","Нет и милей тебя:",0,65,2,0],["v","В златом украшенных",0,66,2,0],["v","Залах отца богов",0,66,2,0],["v","Сколько чарующих,",0,67,2,0],["v","Сколько небесных дев!",0,68,2,0],["v","Ты между них одна",0,69,2,0],["v","Девственно чистая,",0,70,2,1],["v","Солнца отраднее",0,70,2,0],["v","Ты, Артемида, нам.",0,71,2,0],["sd","(Кладут на алтарь <span class=\"ch\" data-ch=\"artemida\">Артемиды</span> цветы и расходятся.)"],["sp","<span class=\"ch\" data-ch=\"ippolit\">Ипполит</span>"],["dir","приближаясь к статуе и окружая ее подножие своей большой гирляндой"],["v","Прими венок, царица: в заповедном<a class=\"nr\" href=\"#n-k5\" data-n=\"k5\" aria-label=\"Примечание 5\">5</a>",0,72,1,0],["v","Лугу, цветы срывая, для тебя",0,73,1,0],["v","Я вил его… На этот луг не смеет",0,74,1,0],["v","Гнать коз пастух, и не касался серп",0,75,1,0],["v","Там нежных трав. Там только пчел весною",0,76,1,0],["v","Кружится рой средь девственной травы.",0,77,1,0],["v","Его росой поит сама Стыдливость.",0,78,1,0],["v","И лишь тому, кто истинно стыдлив",0,79,1,0],["v","Не хитростью, стыдлив душой свободной,",0,80,1,1],["v","Срывать цветы там свежие дано:",0,80,1,0],["v","Для слабых душ они не расцветают.",0,81,1,0],["sd","(Приближаясь к статуе и обнимая ее колена.)"],["v","Но, милая царица, для твоих<a class=\"nr\" href=\"#n-k6\" data-n=\"k6\" aria-label=\"Примечание 6\">6</a>",0,82,1,0],["v","Волос златисто-белых их свивала",0,83,1,0],["v","Среди людей безгрешная рука.",0,83,1,0],["v","Один горжусь я даром — быть с тобою,",0,84,1,0],["v","Дыханьем уст с тобой меняться звучным",0,85,1,0],["v","И голосу внимать, лица не видя…",0,86,1,0],["v","О, если бы, как начинаю путь",0,86,1,0],["v","И обогнув мету, все быть с тобою…",0,87,1,0],["sp","Старый раб"],["dir","подходя к <span class=\"ch\" data-ch=\"ippolit\">Ипполиту</span>, который спустился со ступеней подножия. Старик без шапки, с палкой, говорит сурово"],["v","Царь!.. Для меня лишь боги господа…",0,88,0,0],["v","Готов ли ты принять совет во благо?",0,89,0,0],["sp","<span class=\"ch\" data-ch=\"ippolit\">Ипполит</span>"],["v","Конечно да. Иль мудрости, старик,",0,90,0,1],["v","Иначе мы сберечь могли бы славу?",0,90,0,0],["sp","Старый раб"],["v","Ты знаешь ли, что общий есть закон?",0,91,0,0],["sp","<span class=\"ch\" data-ch=\"ippolit\">Ипполит</span>"],["v","Какой закон? К чему ты речи клонишь?",0,92,0,0],["sp","Старый раб"],["v","Кто сух душой надменной, нам не мил.",0,93,0,0],["sp","<span class=\"ch\" data-ch=\"ippolit\">Ипполит</span>"],["v","Ты прав, старик: надменный ненавистен.",0,94,0,0],["sp","Старый раб"],["v","Лишь ласковый имеет дар пленять.",0,95,0,0],["sp","<span class=\"ch\" data-ch=\"ippolit\">Ипполит</span>"],["v","Он без труда друзей приобретает.",0,96,0,0],["sp","Старый раб"],["v","Не то же ли среди богов, что здесь?..",0,97,0,0],["sp","<span class=\"ch\" data-ch=\"ippolit\">Ипполит</span>"],["v","Раз их закон мы, смертные, приемлем…",0,98,0,0],["sp","Старый раб"],["v","С богинею зачем же ты так горд?",0,99,0,0],["sp","<span class=\"ch\" data-ch=\"ippolit\">Ипполит</span>"],["v","С какой? Смотри — уста на грех наводят.",0,100,0,1],["sp","Старый раб"],["dir","указывая на статую <span class=\"ch\" data-ch=\"afrodita\">Киприды</span>"],["v","С <span class=\"ch\" data-ch=\"afrodita\">Кипридою</span>, хранящей твой порог.",0,101,0,0],["sp","<span class=\"ch\" data-ch=\"ippolit\">Ипполит</span>"],["dir","с полупоклоном к статуе <span class=\"ch\" data-ch=\"afrodita\">Афродиты</span>, не отходя от статуи <span class=\"ch\" data-ch=\"artemida\">Артемиды</span>"],["v","Я чту ее, но издали, как чистый.",0,102,0,0],["sp","Старый раб"],["dir","повышая тон"],["v","Особенно все люди чтут ее.",0,103,0,0],["sp","<span class=\"ch\" data-ch=\"ippolit\">Ипполит</span>"],["v","Бог, дивный лишь во мраке, мне не мил.",0,106,0,1],["sp","Старый раб"],["v","Дитя, воздай богам, что боги любят.",0,105,0,0],["sp","<span class=\"ch\" data-ch=\"ippolit\">Ипполит</span>"],["v","Кому один, кому другой милее,",0,104,0,1],["v","И из богов, и меж людей, старик.",0,105,0,0],["sp","Старый раб"],["dir","помолчав, с расстановкой"],["v","Умен ты, да… Дай бог, чтоб был и счастлив.",0,106,0,0],["sp","<span class=\"ch\" data-ch=\"ippolit\">Ипполит</span>"],["dir","к охотникам"],["v","Свободны вы, товарищи! В дому",0,108,0,1],["v","Нам полный стол отраден после ловли,",0,109,0,0],["v","Подумайте ж о пище — а потом",0,110,0,1],["v","Вы кобылиц почистите. Вкусивши",0,110,0,0],["v","Отрадных яств, я их запречь велю,",0,111,0,0],["v","Ристалищу свободно отдаваясь.",0,112,0,0],["sd","(К старику, который молча стоит около статуи <span class=\"ch\" data-ch=\"afrodita\">Афродиты</span> — с полупоклоном к обоим.)"],["v","Вам много радостей с <span class=\"ch\" data-ch=\"afrodita\">Кипридою</span>, старик!",0,113,0,0],["sd","<span class=\"ch\" data-ch=\"ippolit\">Ипполит</span> уходит в средние двери, свита в левые двери."],["scene","Явление третье","s3",1,3],["v","Старый раб и несколько рабов.",0,114,0,0],["sp","Старый раб"],["dir","после минуты молчания"],["v","Нет, с юных мы примера брать не будем,",0,115,0,0],["v","Коль мыслят так.",0,115,0,0],["sd","(Низко кланяясь <span class=\"ch\" data-ch=\"afrodita\">Афродите</span>, причем палку он кладет на землю, потом воздевает к богине руки.)"],["v","С молитвою к тебе я обращаюсь,",0,116,0,0],["v","Владычица <span class=\"ch\" data-ch=\"afrodita\">Киприда</span>. Снизойди",0,117,0,0],["v","Ты к юности с ее кичливым сердцем",0,118,0,0],["v","И дерзкие слова ее забудь:",0,119,0,0],["v","Нас не на то ль вы, боги, и мудрее?",0,120,0,1],["scene","Явление четвертое","s4",1,4],["scene","Вступительная песнь хора","s5",1,5],["sd","На орхестру правым проходом одна за другой спускаются пятнадцать трезенских женщин, приблизительно в возрасте <span class=\"ch\" data-ch=\"fedra\">Федры</span>. Хор разделяется на два полухория."],["sp","Первое полухорие"],["str","Строфа I"],["v","Холодна, и чиста, и светла",0,120,0,0],["v","От волны океана скала,",0,121,0,0],["v","Там поток, убегая с вершины,",0,122,0,0],["v","И купает и поит кувшины.",0,123,0,0],["v","Там сверкавшие покровы",0,124,1,0],["v","Раным-рано дева мыла,",0,125,1,0],["v","На хребет скалы суровой,",0,125,1,0],["v","Что лучами опалило",0,126,1,0],["v","Колесницы дня багровой,",0,127,1,0],["v","Расстилая, их сушила:",0,128,1,0],["v","О царице вестью новой",0,129,1,0],["v","Нас она остановила.",0,130,1,1],["sp","Второе полухорие"],["str","Антистрофа I"],["v","Ложу скорби судьбой отдана,",0,130,0,0],["v","Больше солнца не видит она,",0,131,0,0],["v","И ланиты с косой золотою",0,132,0,0],["v","За кисейною прячет фатою.",0,133,0,0],["v","Третий день уж наступает,",0,134,1,0],["v","Но губам еще царица",0,135,1,0],["v","Не дала и раствориться,",0,136,1,0],["v","От Деметры дивной брашна,<a class=\"nr\" href=\"#n-k7\" data-n=\"k7\" aria-label=\"Примечание 7\">7</a>",0,137,1,0],["v","Все неведомой томится",0,138,1,0],["v","Мукой, бедная, и страшный",0,139,1,0],["v","Все Аид ей, верно, снится.",0,140,1,1],["sp","Первое полухорие"],["str","Строфа II"],["v","Бредом, царица,",0,140,0,0],["v","Пана бредом объята,<a class=\"nr\" href=\"#n-k8\" data-n=\"k8\" aria-label=\"Примечание 8\">8</a>",0,141,0,0],["v","Или Гекаты, иль горной",0,142,0,0],["v","Реи, иль стаи грозной",0,143,0,0],["v","Бредом полна корибантов ты…",0,144,1,0],["v","Может быть, ты Диктинну,",0,145,1,0],["v","Лова нечестьем царицу,",0,145,1,0],["v","О госпожа, оскорбила,",0,146,1,0],["v","Брашна святого не дав ей?",0,147,1,0],["v","Дивною земли полны,",0,148,1,0],["v","И над пучиною моря",0,149,1,0],["v","Носится тень Диктинны.",0,150,1,1],["sp","Второе полухорие"],["str","Антистрофа II"],["v","Или супруга,",0,150,0,0],["v","Или с ложа, царица,",0,151,0,0],["v","Тайная князя вельможных",0,152,0,0],["v","Связь увлекла, скажи нам?",0,153,0,0],["v","Крита ль брега родимого,",0,154,1,0],["v","Смело ладью вверяя",0,155,1,0],["v","Кинул моряк пучине,",0,155,1,0],["v","Гавани радуясь в мыслях?",0,156,1,0],["v","Может быть, вести царице",0,157,1,0],["v","Путник привез такие,",0,158,1,0],["v","Что ей печаль и мука",0,159,1,0],["v","Души сковали с ложем…",0,160,1,1],["sp","Хор"],["str","Эпод"],["v","Жребий несчастный жен,",0,160,0,0],["v","Разве он тайна мне?",0,161,0,0],["v","Немощи робкие, сколько таится в них",0,162,0,0],["v","Мрака душевного,",0,162,1,0],["v","Сколько безумия —",0,163,1,0],["v","Носят, как мать дитя… Этот порыв",0,164,0,0],["v","Прихоти немощной в сердце и мне проник.",0,165,0,0],["sd","(С молитвенным обращением к статуе <span class=\"ch\" data-ch=\"artemida\">Артемиды</span> и воздеванием рук.)"],["v","Но к <span class=\"ch\" data-ch=\"artemida\">Артемиде</span>, деве небесной,",0,165,1,0],["v","Стрелы носящей, я,",0,166,1,0],["v","В родах хранящей, я",0,167,1,0],["v","Громко взывала.",0,167,1,0],["v","И <span class=\"ch\" data-ch=\"artemida\">Артемида</span> мне между бессмертными",0,168,0,0],["v","Всех и теперь милей.",0,169,1,0],["act","Действие первое","a2","I"],["scene","Явление пятое","s6",2,6],["sd","Жаркий полдень. Из дворца на низком ложе выносят полулежащую <span class=\"ch\" data-ch=\"fedra\">Федру</span>. Она высокая, бледная, губы сухие, с полуспущенным покрывалом на голове. С ней старые кормилицы и служанки, из них некоторые несут царицу, другие покрывала, благовония, опахало. Шествие показывается после первых слов корифея. Старая кормилица и служанки хлопочут около <span class=\"ch\" data-ch=\"fedra\">Федры</span> и укладывают ее на постели, несколько раз передвигая ложе."],["sp","Корифей"],["v","Вот старая няня…",0,170,2,1],["v","За ней из дворца несут сюда ложе царицы.",0,171,0,0],["v","Какая бледная! Как извелась,",0,172,2,0],["v","Как тень бровей ее растет, темнея!",0,173,2,0],["v","О, что с ней?.. Любовью тревожной полна я.",0,174,0,0],["v","Знаки участия и любопытства в хоре.",0,175,0,0],["sp","<span class=\"ch\" data-ch=\"kormilitsa\">Кормилица</span>"],["dir","заметно утомленная возней и тревогой"],["sd","(К хору.)"],["v","О, слабость людская, о, злые недуги!",0,176,0,0],["v","Что делать буду я? Чего мне не делать, скажите?",0,177,0,0],["sd","(К <span class=\"ch\" data-ch=\"fedra\">Федре</span>.)"],["v","И светлое солнце, и чистое небо,",0,178,0,0],["v","Дитя, над твоею недужной постелью…",0,180,0,1],["v","Ты воли просила.",0,180,0,0],["v","«На воздух несите», — рабыням твердила.",0,181,0,0],["v","Минута — и спальня нам будет милее.",0,182,0,0],["v","Желанья что волны. Что тень твоя радость.",0,183,0,0],["v","Что есть — надоело, не мило, а если",0,183,0,0],["v","Чего мы не видим, душа загорелась:",0,184,0,0],["v","Скорее, скорее.",0,185,0,0],["sd","(К хору.)"],["v","Не лучше ль уж, право,",0,186,4,0],["v","Больною лежать, чем ходить за больной?",0,186,0,0],["v","Там тело страдает, а тут и душа",0,187,0,0],["v","Твоя изболеет, и руки устанут…",0,188,0,0],["sd","Пауза."],["v","Да, жизнь человека — лишь мука сплошная,",0,189,0,0],["v","Где цепи мы носим трудов и болезней.",0,190,0,1],["sd","(Задумчиво.)"],["v","Но быть же не может, чтоб нечто милее,",0,190,0,0],["v","Чем путь этот скучный, за облаком темным",0,191,0,0],["v","Для нас не таилось.",0,192,0,0],["v","И если мерцанья",1,192,0,0],["v","Мятежного ищем душой на земле мы,",0,193,0,0],["v","Так только затем, что иной не причастны",0,194,0,0],["v","Мы жизни и глаз человека не властен",0,195,0,0],["v","Подземные тени рассеять лучами,",0,196,0,0],["v","Что лживые сказки душою играют.",0,197,0,0],["sp","<span class=\"ch\" data-ch=\"fedra\">Федра</span>"],["dir","к служанкам, которые ей помогают"],["v","Подняться хочу я… Поднять с изголовья",0,198,0,0],["v","Мне голову дайте… Нет силы… Все тело",0,199,0,0],["v","Мое разломило… За белые руки",0,200,0,1],["v","Возьмите меня вы, за слабые руки.",0,200,0,0],["v","Долой покрывало!",0,201,0,0],["sd","(Срывает покрывало и дает рассыпаться темно-золотистым своим и набегающим на щеки волосам.)"],["v","Мне тяжко, рабыни…",0,202,4,0],["v","Пусть волосы льются и плечи оденут…",0,203,0,0],["sp","<span class=\"ch\" data-ch=\"kormilitsa\">Кормилица</span>"],["dir","склоняясь к ней"],["v","Немного терпенья, дитя, не мечись",0,204,0,0],["v","Так дико… Собою владей, и недуг",0,205,0,0],["v","Тебе покорится. Ты только подумай:",0,206,0,0],["v","Ведь ты ж человек — обреченный страданью.",0,207,0,0],["sp","<span class=\"ch\" data-ch=\"fedra\">Федра</span>"],["dir","приподнимаясь и садясь на ложе, с которого она спускает ноги"],["v","Мне ключ бы гремучий, студеный и чистый:",0,208,0,0],["v","Воды бы оттуда напиться… я после",0,209,0,0],["v","В развесистой куще б улечься хотела,",0,210,0,1],["v","Среди тополей и на зелени нежной.",0,211,0,0],["sp","<span class=\"ch\" data-ch=\"kormilitsa\">Кормилица</span>"],["v","Опомнись, опомнись,",0,212,0,0],["v","Не стыдно ль желанья такие безумно",0,213,0,0],["v","Кидать при народе…",0,214,0,0],["sp","<span class=\"ch\" data-ch=\"fedra\">Федра</span>"],["dir","сходя с ложа"],["sd","Рабыни расступаются, кормилица молча качает головой, обмениваясь знаками недоумения с хором и служанками."],["v","Оставьте… Туда я… Я в горы хочу,",0,215,0,0],["v","Где ели темнее. Где хищные своры",0,216,0,0],["v","За ланью пятнистой гоняются жадно.",0,217,0,0],["sd","(С возрастающей лихорадкой.)"],["v","О, ради богов…",0,218,0,0],["v","Когда бы могла я живить ее свистом,",0,220,0,1],["v","О, если бы дротик к ланите под сенью",0,221,0,0],["v","Волос золотистых приблизить могла я…",0,222,0,0],["sp","<span class=\"ch\" data-ch=\"kormilitsa\">Кормилица</span>"],["v","Уж это откуда желанье, не знаю…",0,223,0,0],["v","По зверю охота — твоя ли забота?",0,224,0,0],["v","А если воды ключевой захотелось,",0,225,0,0],["v","Ходить недалеко — источник у дома,",0,226,0,0],["v","И пей себе, сколько душа твоя просит…",0,227,0,0],["sp","<span class=\"ch\" data-ch=\"fedra\">Федра</span>"],["v","Туда, Артемида, царица приморья,",0,228,0,0],["v","Где кони песчаные отмели топчут!",0,229,0,0],["v","О, если б туда мне, в урочища девы,",0,230,0,1],["v","И мне четверню бы венетскую в мыле.<a class=\"nr\" href=\"#n-k10\" data-n=\"k10\" aria-label=\"Примечание 10\">10</a>",0,231,0,0],["sp","<span class=\"ch\" data-ch=\"kormilitsa\">Кормилица</span>"],["dir","всплеснув руками"],["v","Чего еще просит? Безумные речи!",0,232,0,0],["v","То в горы, по чаще лесистой с охотой",0,233,0,0],["v","За ланью гоняться… то ей на прибрежье",0,234,0,0],["v","Подай колесницу… Гадателя надо,",0,235,0,0],["v","Чтоб бога нам назвал, которому в мысли",0,236,0,0],["v","Пришло твой рассудок с дороги обычной",0,237,0,0],["v","Увлечь в эти дебри. Здесь вещего надо.",0,238,0,0],["sp","<span class=\"ch\" data-ch=\"fedra\">Федра</span>"],["dir","мало-помалу приходит в себя, она видит хор, служанок и, закрывая лицо руками, тихо отходит к своему месту"],["v","Несчастная! Что я? Что сделала я?",0,239,0,0],["v","Где разум? Где стыд мой? Увы мне! Проклятье!",0,240,0,1],["v","Злой демон меня поразил… Вне себя я",0,241,0,0],["v","Была… бесновалась… Увы мне! Увы!",0,242,0,0],["sd","(Ложится.)"],["v","Покрой меня, няня, родная, покрой…",0,243,0,0],["v","Мне стыдно безумных речей…",0,244,0,0],["v","О, спрячь меня! Слез не удержишь… бегут.",0,245,0,0],["v","И щеки горят от стыда… возвращаться",0,246,0,0],["v","К сознанью так больно, что, кажется, лучше,",0,247,0,0],["v","Когда б умереть я могла, не проснувшись.",0,248,0,0],["sp","<span class=\"ch\" data-ch=\"kormilitsa\">Кормилица</span>"],["dir","покрывая <span class=\"ch\" data-ch=\"fedra\">Федру</span>"],["v","Закрыла… Чего уж? Самой-то в могиле",0,250,0,1],["v","Скорей бы землею покрыться. Судьба ведь",0,251,0,0],["v","За долгие годы чему не научит…",0,252,0,0],["sd","(К хору.)"],["v","Не надо, чтоб люди так сильно друг друга",0,253,0,0],["v","Любили. Пусть узы свободнее будут,",0,254,0,0],["v","Чтоб можно их было стянуть и ослабить,",0,255,0,0],["v","А так вот, как я эту <span class=\"ch\" data-ch=\"fedra\">Федру</span> люблю,",0,256,0,0],["v","Любить — это тяжкое бремя. На сердце",0,257,0,0],["v","Одно, да заботы, да страхи двойные.",0,260,0,1],["v","Вот подлинно — где ты уж слишком усерден,",0,261,0,0],["v","Там много ошибок да мало утехи…",0,262,0,0],["v","Всегда я скажу: ты излишнего бойся,",0,263,0,0],["v","Все в меру — и мудрые скажут: все в меру.",0,264,0,0],["sd","(Отходит от <span class=\"ch\" data-ch=\"fedra\">Федры</span>, которая лежит молча, закрывшись. Дальше сцена ведется вполголоса.)"],["sp","Корифей"],["v","Ты, старая и верная раба,",0,265,0,0],["v","Вспоившая царицу! Видим, горе<a class=\"nr\" href=\"#n-k9\" data-n=\"k9\" aria-label=\"Примечание 9\">9</a>",0,266,0,0],["v","Какое-то у <span class=\"ch\" data-ch=\"fedra\">Федры</span>, но понять,",0,267,0,0],["v","Какой недуг у ней, — не понимаем.",0,268,0,0],["v","Душа горит твоих послушать слов.",0,270,0,1],["sp","<span class=\"ch\" data-ch=\"kormilitsa\">Кормилица</span>"],["v","Когда б сама я, жены, понимала…",0,271,0,0],["sp","Корифей"],["v","Причину мук ты знаешь, может быть.",0,272,0,0],["sp","<span class=\"ch\" data-ch=\"kormilitsa\">Кормилица</span>"],["v","И тоже нет. Она давно таится.",0,273,0,0],["sp","Корифей"],["v","А как слаба она… Как извелась…",0,274,0,0],["sp","<span class=\"ch\" data-ch=\"kormilitsa\">Кормилица</span>"],["v","Не ослабеть… как третий день без пищи!",0,275,0,0],["sp","Корифей"],["v","В безумии она?.. Иль смерти жаждет?",0,276,0,0],["sp","<span class=\"ch\" data-ch=\"kormilitsa\">Кормилица</span>"],["v","Конец один. Причины ж я не знаю.",0,277,0,0],["sp","Корифей"],["v","На мужа я дивлюсь… Что ж смотрит муж?",0,278,0,0],["sp","<span class=\"ch\" data-ch=\"kormilitsa\">Кормилица</span>"],["v","Я ж говорю тебе — она таится.",0,279,0,0],["sp","Корифей"],["v","Но на лице нельзя ж не видеть мук.",0,280,0,1],["sp","<span class=\"ch\" data-ch=\"kormilitsa\">Кормилица</span>"],["v","Да, как на грех, и муж у ней в отъезде.",0,280,0,0],["sp","Корифей"],["v","Но ты? Ужель на все ты не пойдешь,",0,281,0,0],["v","Чтобы недуг ее разведать, тело",0,282,0,0],["v","И душу ей снедающий недуг?..",0,283,0,0],["sp","<span class=\"ch\" data-ch=\"kormilitsa\">Кормилица</span>"],["v","Старалась уж, да никакого проку.",0,283,1,0],["v","Но рук я не сложу — смотрите все",0,284,1,0],["v","И помните, что господам в несчастье",0,285,1,0],["v","Я верная слуга…",0,286,1,0],["sd","(Подходит к <span class=\"ch\" data-ch=\"fedra\">Федре</span>, наклоняется над ней, говорит что-то шепотом, на что <span class=\"ch\" data-ch=\"fedra\">Федра</span> отрицательно качает головой, потом громко:)"],["v","Дитя мое",0,286,4,0],["v","Любимое, мы прежних лучше обе",0,287,1,0],["v","Не будем слов и помнить… Ты смягчись",0,288,1,0],["v","И не гляди так гневно… Я ж покину",0,289,1,0],["v","Унылый путь, которым мрачный ум",0,290,2,1],["v","Дошел до слов тяжелых, и другую",0,290,1,0],["v","Речь заведу, получше.",0,291,1,0],["v","Если тайным",1,291,0,0],["v","Недугом ты страдаешь, эти жены",0,292,1,0],["sd","(указывая на хор)"],["v","Тебе помогут опытом, стараньем;",0,293,1,0],["v","А если он таков, чтоб и мужам",0,294,1,0],["v","Его открыть, — тебя врачи излечат.",0,295,1,0],["v","Что ж ты молчишь, дитя? Хоть что-нибудь",0,296,1,0],["v","Скажи, меня, коли не так сказала,",0,297,1,0],["v","Оспорь, а не оспоришь, так признай,",0,298,1,0],["v","Что я права, и поступи согласно",0,299,1,0],["v","Моим словам. Открой же губы… Дай",0,300,2,1],["v","Хоть посмотреть в глаза тебе… О, горе!",0,300,1,0],["v","Вот, женщины… Вы видите? Опять.",0,301,1,0],["v","Уж я ли не старалась?.. Все напрасно:",0,302,1,0],["v","Как было, так и есть, и как тогда",0,302,1,0],["v","Была глуха, так и теперь не внемлет.",0,303,1,0],["sd","Пауза."],["sd","(Отходит от <span class=\"ch\" data-ch=\"fedra\">Федры</span>, говорит с хором, потом опять уже более решительно подходит к ней и говорит более суровым тоном.)"],["v","Пойми ж ты хоть одно. К другому можешь",0,304,1,0],["v","Ты равнодушней моря быть, но если",0,304,1,0],["v","Себя убьешь, — ведь собственных детей",0,305,1,0],["v","Отцовской ты лишаешь части этим.",0,306,1,0],["v","Я царственной наездницей клянусь,",0,306,1,0],["v","Что детям родила твоим владыку,<a class=\"nr\" href=\"#n-k11\" data-n=\"k11\" aria-label=\"Примечание 11\">11</a>",0,307,1,0],["v","Пусть незаконного, но с честолюбьем,",0,308,1,0],["v","Законного достойным. Ты его",0,308,1,0],["v","Отлично знаешь, Федра… <span class=\"ch\" data-ch=\"ippolit\">Ипполита</span>.",0,309,1,0],["sp","<span class=\"ch\" data-ch=\"fedra\">Федра</span>"],["dir","не поднимая фаты, но привстав"],["v","Увы!<a class=\"nr\" href=\"#n-k12\" data-n=\"k12\" aria-label=\"Примечание 12\">12</a>",0,310,0,1],["sp","<span class=\"ch\" data-ch=\"kormilitsa\">Кормилица</span>"],["dir","с живостью"],["v","Коснулась я живого места разве?",0,310,0,0],["sp","<span class=\"ch\" data-ch=\"fedra\">Федра</span>"],["dir","садится на постели и полуспускает фату"],["v","Ты сделала мне больно… Я молю:",0,311,0,0],["v","Не повторяй мне больше это имя.",0,312,0,0],["sp","<span class=\"ch\" data-ch=\"kormilitsa\">Кормилица</span>"],["v","Вот видишь ты — сама ведь поняла;",0,312,0,0],["v","Так как же, рассудив, не хочешь жизни",0,313,0,0],["v","Своей сберечь для собственных детей?",0,314,0,0],["sp","<span class=\"ch\" data-ch=\"fedra\">Федра</span>"],["v","Я их люблю, детей. Но в сердце буря",0,315,0,0],["v","Мне жребием ниспослана иным.",0,315,0,0],["sp","<span class=\"ch\" data-ch=\"kormilitsa\">Кормилица</span>"],["v","Нет на руках твоих, надеюсь, крови?",0,316,0,0],["sp","<span class=\"ch\" data-ch=\"fedra\">Федра</span>"],["v","Душа во мне… душа заражена.",0,317,0,0],["sp","<span class=\"ch\" data-ch=\"kormilitsa\">Кормилица</span>"],["v","Иль это враг тебе какой подстроил?",0,317,0,0],["sp","<span class=\"ch\" data-ch=\"fedra\">Федра</span>"],["v","О нет, мы зла друг другу не хотим;",0,318,0,0],["v","Но он убьет, и я убита буду.",0,319,0,0],["sp","<span class=\"ch\" data-ch=\"kormilitsa\">Кормилица</span>"],["v","Перед тобой <span class=\"ch\" data-ch=\"tesey\">Тесей</span> не согрешил?",0,320,0,1],["sp","<span class=\"ch\" data-ch=\"fedra\">Федра</span>"],["v","Мне перед ним не согрешить бы только.",0,321,0,0],["sp","<span class=\"ch\" data-ch=\"kormilitsa\">Кормилица</span>"],["v","Но что ж тебя в Аидов дом влечет?",0,322,0,0],["sp","<span class=\"ch\" data-ch=\"fedra\">Федра</span>"],["v","Мой грех — тебя касаться он не может.",0,323,0,0],["sp","<span class=\"ch\" data-ch=\"kormilitsa\">Кормилица</span>"],["dir","припадая к ней, плачет"],["v","Конечно нет. Но ты покинешь нас…",0,324,0,0],["sp","<span class=\"ch\" data-ch=\"fedra\">Федра</span>"],["v","Оставь, оставь! Зачем к руке припала?",0,325,0,0],["sp","<span class=\"ch\" data-ch=\"kormilitsa\">Кормилица</span>"],["dir","бросаясь к ее ногам"],["v","В мольбе твоих не выпущу колен.",0,326,0,0],["sp","<span class=\"ch\" data-ch=\"fedra\">Федра</span>"],["v","Тебе же мука, коль узнаешь, мука…",0,327,0,0],["sp","<span class=\"ch\" data-ch=\"kormilitsa\">Кормилица</span>"],["v","Нет большей мне, как <span class=\"ch\" data-ch=\"fedra\">Федру</span> потерять.",0,328,0,0],["sp","<span class=\"ch\" data-ch=\"fedra\">Федра</span>"],["v","Она умрет, но не бесславной смертью.",0,329,0,0],["sp","<span class=\"ch\" data-ch=\"kormilitsa\">Кормилица</span>"],["v","А слава в чем? Хоть это мне скажи.",0,330,0,1],["sp","<span class=\"ch\" data-ch=\"fedra\">Федра</span>"],["v","Ее добуду на стезе греха.",0,330,0,0],["sp","<span class=\"ch\" data-ch=\"kormilitsa\">Кормилица</span>"],["v","Откройся ж нам — и слава возрастет.",0,331,0,0],["sp","<span class=\"ch\" data-ch=\"fedra\">Федра</span>"],["dir","вставая, причем кормилица не хочет оставить ее руки и влечется за ней"],["v","Уйди, молю… Освободи мне руку…",0,332,0,0],["sp","<span class=\"ch\" data-ch=\"kormilitsa\">Кормилица</span>"],["v","Нет, ни за что… Молящий дара ждет.",0,333,0,0],["sp","<span class=\"ch\" data-ch=\"fedra\">Федра</span>"],["v","И ты получишь этот дар молящих.",0,334,0,0],["sp","<span class=\"ch\" data-ch=\"kormilitsa\">Кормилица</span>"],["v","Тогда молчу… но за тобою речь…",0,335,0,0],["sp","<span class=\"ch\" data-ch=\"fedra\">Федра</span>"],["dir","вставая и простирая руки к небу, как бы про себя"],["v","Какой любви ты сердце отдавала,",0,335,0,0],["v","О мать, о мать несчастная моя!",0,336,0,0],["sp","<span class=\"ch\" data-ch=\"kormilitsa\">Кормилица</span>"],["v","Ты вспомнила быка иль что другое?",0,337,0,0],["sp","<span class=\"ch\" data-ch=\"fedra\">Федра</span>"],["v","О, бедная, и той же рождена",0,338,0,0],["v","Для ложа Диониса Ариадна…",0,339,0,0],["sp","<span class=\"ch\" data-ch=\"kormilitsa\">Кормилица</span>"],["v","Опомнись, дочь… ты свой порочишь род.",0,340,0,1],["sp","<span class=\"ch\" data-ch=\"fedra\">Федра</span>"],["v","Мне третьей быть добычей смерти, третьей.",0,340,0,0],["sp","<span class=\"ch\" data-ch=\"kormilitsa\">Кормилица</span>"],["v","О, ужас… О, куда ж ты клонишь речь?",0,341,0,0],["sp","<span class=\"ch\" data-ch=\"fedra\">Федра</span>"],["v","Туда, где злой давно таится жребий.",0,342,0,0],["sp","<span class=\"ch\" data-ch=\"kormilitsa\">Кормилица</span>"],["v","Но в чем же он?.. Когда бы знать могла я!",0,343,0,0],["sp","<span class=\"ch\" data-ch=\"fedra\">Федра</span>"],["v","О, горе мне… Когда б мои слова",0,344,0,0],["v","Ты, женщина, сама сказать могла бы.",0,345,0,0],["sp","<span class=\"ch\" data-ch=\"kormilitsa\">Кормилица</span>"],["v","Я ж не пророк, чтоб чудом их узнать.",0,346,0,0],["sp","<span class=\"ch\" data-ch=\"fedra\">Федра</span>"],["v","Ты знаешь ли, что это значит — «любит»?",0,347,0,0],["sp","<span class=\"ch\" data-ch=\"kormilitsa\">Кормилица</span>"],["v","Да, слаще нет, дитя, и нет больней…",0,348,0,0],["sp","<span class=\"ch\" data-ch=\"fedra\">Федра</span>"],["v","Последнее — вот мой удел, родная.",0,349,0,0],["sd","Пауза."],["sp","<span class=\"ch\" data-ch=\"kormilitsa\">Кормилица</span>"],["dir","упавшим голосом"],["v","Что слышу я? Ты любишь? Но кого ж?",0,350,0,1],["sp","<span class=\"ch\" data-ch=\"fedra\">Федра</span>"],["dir","тихо"],["v","Не знаю кто, но сын он амазонки.",0,350,0,0],["sp","<span class=\"ch\" data-ch=\"kormilitsa\">Кормилица</span>"],["v","Как… Ипполит?..",0,351,0,0],["sp","<span class=\"ch\" data-ch=\"fedra\">Федра</span>"],["v","Он назван, но не мной.",1,351,0,0],["sp","<span class=\"ch\" data-ch=\"kormilitsa\">Кормилица</span>"],["dir","с жестами отчаяния"],["v","Не может быть, дитя. Ты убиваешь<a class=\"nr\" href=\"#n-k13\" data-n=\"k13\" aria-label=\"Примечание 13\">13</a>",0,352,0,0],["v","Признанием меня. Для старых плеч",0,353,0,0],["v","Такое иго, жены, слишком тяжко.",0,354,0,0],["v","Проклятый день, проклятый свет очей…",0,355,0,0],["v","Нет, в омут мне… Но только эту ношу",0,355,0,0],["v","Берите прочь… На что ж и жизнь, когда",0,356,0,0],["v","Порок возьмет насильем добродетель",0,357,0,0],["v","Влюбленную?",0,358,0,0],["sd","(К статуе <span class=\"ch\" data-ch=\"afrodita\">Киприды</span>.)"],["v","<span class=\"ch\" data-ch=\"afrodita\">Киприда</span> — ты не бог,",0,359,0,0],["v","Ты больше бога. Кто б ты ни была,",0,360,0,1],["v","Но <span class=\"ch\" data-ch=\"fedra\">Федру</span>, и меня, и дом сгубила.",0,360,0,0],["sp","Корифей"],["v","Вы слышали, подруги?",0,361,0,0],["v","Из царских губ внимали ль вы",0,362,0,0],["v","Неслыханным речам, речам ужасным?",0,362,0,0],["v","О, лучше бы, о, лучше б умереть,",0,363,0,0],["v","Покуда в грудь мою",0,364,0,0],["v","Твои слова проникнуть не успели.",0,365,0,0],["v","Всем горе, всем нам горе, всем нам горе!",0,365,0,0],["v","Несчастная! Какой ужасный рок",0,366,0,0],["v","Тобой владел?.. О, смертные!.. О, род,",0,367,0,0],["v","На муки обреченный! Ты погибла,",0,367,0,0],["v","Отдав лучам позор… Как этот день тебе",0,368,0,0],["v","Короткий пережить еще?..",0,369,0,0],["v","К концу идет с тобою царский дом,",0,370,0,1],["v","И больше тайны нет, куда <span class=\"ch\" data-ch=\"afrodita\">Киприды</span>,",0,370,0,0],["v","Тебя склоняя, воля губит,",0,371,0,0],["v","О Пасифаи дочь несчастная, о Федра!",0,372,0,0],["sp","<span class=\"ch\" data-ch=\"fedra\">Федра</span>"],["dir","собралась с силами, и в следующей речи уже чувствуется полное самообладание"],["v","Вы, дочери Трезена, вы краса",0,373,0,0],["v","Преддверия Пелоповой державы,<a class=\"nr\" href=\"#n-k14\" data-n=\"k14\" aria-label=\"Примечание 14\">14</a>",0,374,0,0],["v","Уже давно в безмолвии ночей",0,375,0,0],["v","Я думою томилась: в жизни смертных",0,376,0,0],["v","Откуда ж эта язва? Иль ума",0,377,0,0],["v","Природа виновата в заблужденьях?..",0,378,0,0],["v","Нет — рассужденья мало — дело в том,",0,379,0,0],["v","Что к доброму мы не стремимся вовсе,",0,380,0,1],["v","Не в том, что мы его не знаем. Да,",0,380,0,0],["v","Одним мешает леность, а другой",0,381,0,0],["v","Не знает даже вкуса в наслажденье",0,382,0,0],["v","Исполненного долга. Мир — увы! —",0,382,0,0],["v","Соблазнов полн, и, если волны речи",0,383,0,0],["v","Людской нас не закружат, — праздность нас,",0,384,0,0],["v","За радостью гоняя, обессилит…",0,384,0,0],["v","Ты скажешь, стыд?.. Какой? Есть два стыда:",0,385,0,0],["v","Священный стыд и ложный, но тяжелый.",0,386,0,0],["v","А будь меж них светла для света грань,",0,386,0,0],["v","Они одним бы словом не писались…",0,387,0,0],["v","И вот с тех пор, как тяжким размышленьем",0,388,0,0],["v","Я различать их научилась, нет",0,388,0,0],["v","Мне более к неведенью возврата,",0,389,0,0],["v","И не могу не видеть я греха.",0,390,0,1],["v","Но я хочу с тобою проследить",0,390,0,0],["v","Решенья ход… Когда Эрота жало",0,391,0,0],["v","Я в сердце ощутила, как его",0,392,0,0],["v","Переносить, я стала думать честно…",0,393,0,0],["v","И начала с того, чтоб затаить",0,394,0,0],["v","Его как можно глубже. Проку мало",0,395,0,0],["v","Для нас в речах. Пусть иногда язык",0,395,0,0],["v","Поможет нам другого образумить,",0,396,0,0],["v","Но раны нет больней, чем от него.",0,397,0,0],["sd","Пауза."],["v","Я думала потом, что пыл безумный",0,398,0,0],["v","Осилю добродетелью…",0,399,0,0],["v","И вот,",1,399,0,0],["v","Когда ни тайна, ни борьба к победе",0,400,0,1],["v","Не привели меня —",0,400,0,0],["sd","(тихо)"],["v","осталась смерть",0,401,4,0],["sd","Возгласы в хоре."],["v","И это лучший выход. Нет, не надо",0,402,0,0],["v","Мне возражать. Для славы мы хотим",0,403,0,0],["v","Свидетелей… для горя только тайны…",0,404,0,0],["v","Я знала все — недуг… его позор…",0,405,0,0],["v","И женскому я сердцу цену знала…",0,406,0,0],["sd","Пауза."],["v","Пускай для той проклятий будет мало",0,407,0,0],["v","Со всей земли, которая с другим",0,408,0,0],["v","Впервые обманула мужа. О,",0,409,0,0],["v","Пойти с верхов должна была зараза.",0,410,0,1],["v","Ведь если зло — игрушка знатных, разве",0,410,0,0],["v","В толпе оно не станет божеством?",0,411,0,0],["v","Проклятие и вам, чьи скромны речи,",0,412,0,0],["v","Но чьи под кровом ночи черной дерзки",0,413,0,0],["v","Преступные объятья… Как они",0,414,0,0],["v","Решаются, о, пеною богиня",0,415,0,0],["v","Рожденная, потом смотреть в глаза",0,415,0,0],["v","Обманутым мужьям? Как им не страшно,",0,416,0,0],["v","Что самый мрак их выдаст, что стена",0,417,0,0],["v","Заговорит, внимавшая лобзаньям?",0,418,0,0],["v","Я от одной бы мысли умерла,",0,419,0,0],["v","Что мужа бы могла я обесчестить",0,420,0,1],["v","Или детей. Нет, никогда! Они,",0,420,0,0],["v","Свободные и гордые, на землю",0,421,0,0],["v","Священную прославленных Афин",0,422,0,0],["v","Вступая, нас не постыдятся вспомнить.",0,423,0,0],["v","Ведь самый дерзкий клонит, точно раб,",0,423,0,0],["v","К земле чело, когда при нем напомнят",0,424,0,0],["v","Клеймо отца иль матери позор.",0,425,0,0],["v","И если что-нибудь поспорить может",0,426,1,0],["v","С желаньем жить, так совесть, у кого<a class=\"nr\" href=\"#n-k15\" data-n=\"k15\" aria-label=\"Примечание 15\">15</a>",0,426,0,0],["v","Она еще осталась… Слабодушным,",0,427,0,0],["v","Как красной девице, когда-нибудь",0,428,0,0],["v","Подносит время зеркало, но я,",0,429,0,0],["v","Нет, я его не буду дожидаться…",0,430,0,1],["sp","Корифей"],["v","Увы! Увы! Нет в мире ничего",0,430,0,0],["v","Прекраснее, чем добродетель: смертных",0,431,0,0],["v","Она дарит заслуженной хвалой…",0,432,0,0],["sd","Пауза."],["sp","<span class=\"ch\" data-ch=\"kormilitsa\">Кормилица</span>"],["dir","неуверенно приближаясь к <span class=\"ch\" data-ch=\"fedra\">Федре</span>"],["v","О госпожа, когда завесу с бед",0,432,0,0],["v","Ты сдернула так быстро, то, конечно,",0,433,0,0],["v","В испуге я не выбирала слов",0,434,0,0],["v","И лишнее сказать могла. Но дело",0,435,0,0],["v","Совсем не так уж страшно… И всегда",0,435,0,0],["v","Надежнее второе рассужденье.",0,436,0,0],["v","Чего-нибудь неслыханного я",0,437,0,0],["v","Покуда не узнала. <span class=\"ch\" data-ch=\"afrodita\">Афродиты</span>",0,437,0,0],["v","Здесь чары несомненны. Любишь ты?",0,438,0,0],["v","Но не одна ж. Другие тоже любят.",0,439,0,0],["v","И убивать себя!.. Да разве ж всех,",0,440,0,1],["v","Кто любит иль любви готов отдаться,",0,440,0,0],["v","За это и казнить?",0,441,0,0],["v","Да польза ж в чем?",1,441,0,0],["v","Или поток <span class=\"ch\" data-ch=\"afrodita\">Киприды</span> остановишь?",0,442,0,0],["v","Ты уступи ему — тебя волной",0,443,0,0],["v","Он ласково обнимет, а попробуй",0,444,0,0],["v","Надменно или нагло спорить с ним, —",0,445,0,0],["v","И что ж? Тебя не искалечит, скажешь?",0,445,0,0],["v","И в высоте эфирной, и в морской",0,446,0,0],["v","Пучине — власть <span class=\"ch\" data-ch=\"afrodita\">Киприды</span>, и повсюду",0,447,0,0],["v","Творения ее. Она в сердцах",0,448,0,0],["v","Рождает страсть, и все в ее кошнице",0,449,0,0],["v","Мы зернами когда-то были.",0,450,0,1],["v","Кто",1,450,0,0],["v","Истории читал седые свитки",0,450,0,0],["v","Иль песни разучил поэтов, знает,",0,451,0,0],["v","Как некогда Семелы царь богов",0,452,0,0],["v","Безумно ложа жаждал, как Кефала",0,453,0,0],["v","В чертог Эо для ласок увлекла,",0,454,0,0],["v","Румяная. Среди богов и в небе",0,455,0,0],["v","Они живут, однако ж, и теперь",0,456,0,0],["v","И страсти той несут покорно иго…",0,457,0,0],["v","А ты, ты будешь спорить? Если так",0,458,0,0],["v","Тебе тяжел закон богов, то жалко,",0,459,0,0],["v","Что твой отец зараньше для тебя",0,460,0,1],["v","Не вымолил другого иль в утробе",0,460,0,0],["v","Другим богам тебя не посвятил.",0,461,0,0],["sd","Пауза."],["sd","(Подходит еще ближе и говорит еще смиреннее.)"],["v","Таких мужей, что на грехи жены",0,462,1,0],["v","Глаза благоразумно закрывают…",0,463,1,0],["v","Я более скажу… Таких отцов,",0,464,1,0],["v","Что сыновьям не прочь в делах любовных",0,465,1,0],["v","Способствовать. Да умный человек",0,465,1,0],["v","И всякий так рассудит, что дурное",0,466,1,0],["v","Не напоказ. А жизни все равно",0,467,1,0],["v","Не вымерять, как дома. И карниз",0,468,1,0],["v","Ведь не всегда положишь по заказу…",0,469,1,0],["v","Ужели же судьбы — да и какой",0,470,1,1],["v","Еще судьбы! — теченье ты осилишь…",0,470,1,0],["v","Ты — женщина, и если ты могла<a class=\"nr\" href=\"#n-k16\" data-n=\"k16\" aria-label=\"Примечание 16\">16</a>",0,471,1,0],["v","Быть честною не реже, чем нечестной,",0,472,1,0],["v","Считай себя счастливой. Черных дум",0,473,1,0],["v","Останови ж теченье! Это людям",0,473,1,0],["v","Доступнее… А рваться одолеть",0,474,1,0],["v","Богов, дитя, — поверь мне, только гордость.",0,475,1,0],["v","Любить тебе велела <span class=\"ch\" data-ch=\"afrodita\">Афродита</span>…",0,476,1,0],["sd","(Касаясь ее плеча. <span class=\"ch\" data-ch=\"fedra\">Федра</span> сначала вздрагивает, потом легче поддается ее ласкам.)"],["v","Ты будь смелей — осиливай недуг,",0,476,1,0],["v","Захватывай его… На то есть чары,",0,477,1,0],["v","Соблазны слов… Подумаем — найдем",0,478,1,0],["v","И от твоей болезни мы лекарство:",0,479,1,0],["v","Мужчина бы не скоро отыскал:",0,480,1,1],["v","А мы куда на выдумки горазды…",0,481,1,0],["sd","Пауза."],["sd","По знаку <span class=\"ch\" data-ch=\"fedra\">Федры</span> кормилица, не оборачиваясь, делает три шага назад, не переставая, однако, глядеть на <span class=\"ch\" data-ch=\"fedra\">Федру</span> и как бы готовя новый удар."],["sp","Корифей"],["dir","тихо и торжественно <span class=\"ch\" data-ch=\"fedra\">Федре</span>"],["v","Ее слова страдальческой судьбе",0,482,0,0],["v","Отрадное сулят успокоенье,",0,483,0,0],["v","Но я несу, царица, восхищенье,",0,484,0,0],["v","Пусть горькое, но все-таки тебе…",0,485,0,0],["sp","<span class=\"ch\" data-ch=\"fedra\">Федра</span>"],["dir","в тон ей"],["v","О, злая лесть — на сладостной облаве<a class=\"nr\" href=\"#n-k17\" data-n=\"k17\" aria-label=\"Примечание 17\">17</a>",0,486,0,0],["v","Твоих сетей всегда обилен лов.",0,487,0,0],["v","Я не хочу отрадной неги слов,",0,488,0,0],["v","Пускай они мне говорят о славе…",0,489,0,0],["sp","<span class=\"ch\" data-ch=\"kormilitsa\">Кормилица</span>"],["dir","выждав минуту и улыбаясь"],["v","Да, музыка!.. Но эти ризы слов<a class=\"nr\" href=\"#n-k18\" data-n=\"k18\" aria-label=\"Примечание 18\">18</a>",0,490,0,1],["v","Узорные… зачем они? Ведь сердцу ж",0,490,0,0],["v","Лишь <span class=\"ch\" data-ch=\"ippolit\">Ипполита</span> речь была б отрадна.",0,491,0,0],["sd","<span class=\"ch\" data-ch=\"fedra\">Федра</span> вздрагивает и погружается в мысли; тогда кормилица — смелее —"],["v","Зачем же прямо так и не сказать?",0,492,0,0],["v","Тянуть зачем, когда вопрос поставлен",0,492,0,0],["v","Решительный — о жизни? Будь сама",0,493,0,0],["v","Женою ты разумной и спокойной,",0,494,0,0],["v","Иль думаешь: тебе бы этот шаг",0,495,0,0],["v","Я предлагать решилась… для утехи?",0,495,0,0],["v","Но речь идет о жизни… И никто",0,496,0,0],["v","Меня, надеюсь, жены, не осудит.",0,497,0,0],["v","Последние слова обращены к хору.",0,497,0,0],["sp","<span class=\"ch\" data-ch=\"fedra\">Федра</span>"],["v","О, ужас, ужас!.. Замолчишь ли ты?",0,498,0,0],["v","Иль ток речей позорных не иссякнул?..",0,499,0,0],["sp","<span class=\"ch\" data-ch=\"kormilitsa\">Кормилица</span>"],["dir","не без некоторого ехидства"],["v","Позорных! Пусть… Позорные слова",0,500,0,1],["v","Теперь тебе полезней благородных…",0,500,0,0],["v","Не лучше ль жизнь усилием спасти,",0,501,0,0],["v","Чем славою венчать твою могилу?",0,502,0,0],["sp","<span class=\"ch\" data-ch=\"fedra\">Федра</span>"],["dir","складывая руки, с мольбою в голосе"],["v","О нет! О нет, ради богов. Права",0,503,0,0],["v","Ты, да, я знаю… Но позор не меньше",0,503,0,0],["v","От этого. Я цепь Эрота с честью",0,504,0,0],["v","Еще носить хочу… Но ты ведь в бездну",0,505,0,0],["v","Меня зовешь… О нет, о нет, о нет!..",0,506,0,0],["sp","<span class=\"ch\" data-ch=\"kormilitsa\">Кормилица</span>"],["dir","чувствуя слабеющий отпор, подходит к <span class=\"ch\" data-ch=\"fedra\">Федре</span> смелей. В голосе слышится некоторая фамильярность от сознания своей силы"],["v","Ну, рассуди ж… Кто спорит… было б лучше",0,506,0,0],["v","Не полюбить. А полюбила ты,",0,507,0,0],["v","Так не беда: найдем мы исцеленье.",0,508,0,0],["v","Есть у меня и средство от недуга",0,509,0,0],["v","Любовного — ни чести не вредит,",0,510,0,1],["v","Ни разума оно не потемняет…{*}",0,510,0,0],["v","{* Но не плошай: по ком душа горит,",0,511,0,0],["v","Пусть ризы край иль локон потеряет,",0,512,0,0],["v","И вас потом водой не разольешь.}",0,513,0,0],["sp","<span class=\"ch\" data-ch=\"fedra\">Федра</span>"],["dir","равнодушно, как под влиянием гипноза"],["v","Питье иль мазь твое лекарство, няня?",0,514,0,0],["sp","<span class=\"ch\" data-ch=\"kormilitsa\">Кормилица</span>"],["v","В том пользы нет, что много будешь знать.",0,515,0,0],["sp","<span class=\"ch\" data-ch=\"fedra\">Федра</span>"],["v","Но хитрости твои мне страшны… Нет ли",0,516,0,0],["v","Дурного в них… Опасного чего?",0,517,0,0],["sp","<span class=\"ch\" data-ch=\"kormilitsa\">Кормилица</span>"],["v","Чего же ты боишься, не пойму я…",0,518,0,0],["sp","<span class=\"ch\" data-ch=\"fedra\">Федра</span>"],["v","Речей твоих, чтоб о беде моей",0,519,0,0],["v","Тесеев сын по ним не догадался…",0,520,0,1],["sp","<span class=\"ch\" data-ch=\"kormilitsa\">Кормилица</span>"],["dir","спешит уйти, как бы боясь, что настроение <span class=\"ch\" data-ch=\"fedra\">Федры</span> изменится"],["v","И, полно… Все улажу я, дитя.",0,520,0,0],["sd","(К статуе <span class=\"ch\" data-ch=\"afrodita\">Киприды</span>.)"],["v","Ты только будь за нас теперь, Киприда,",0,521,0,0],["v","Владычица морская… Остальное",0,522,0,0],["sd","(с полупоклоном к хору)"],["v","Не перейдет за тесный круг друзей…",0,523,0,0],["sd","(Уходит в среднюю дверь. <span class=\"ch\" data-ch=\"fedra\">Федра</span> в раздумье садится на ложе.)"],["scene","Первый музыкальный антракт","s7",2,7],["sp","Хор"],["str","Строфа I"],["v","О Эрот! О Эрот!",0,524,0,0],["v","На кого ополчился ты,",0,525,0,0],["v","Тем глаза желанье туманит,",0,526,0,0],["v","В сердце сладкая нега льется…",0,527,0,0],["v","Но ко мне не иди, молю тебя,",0,528,0,0],["v","Ни с бедой, Эрот, ни в ярости.",0,529,0,0],["v","Нет такого огня, и лучи светил",0,530,0,1],["v","Со стрелой не сравняются горние,",0,531,0,0],["v","Что из рук своих мечет в нас",0,532,0,0],["v","Дня сын, и стрелой Кипридиной…",0,533,0,0],["str","Антистрофа I"],["v","Слепота! Слепота!<a class=\"nr\" href=\"#n-k19\" data-n=\"k19\" aria-label=\"Примечание 19\">19</a>",0,534,0,0],["v","Аполлону кровавые<a class=\"nr\" href=\"#n-k20\" data-n=\"k20\" aria-label=\"Примечание 20\">20</a>",0,535,0,0],["v","Мечем мы на бреге Алфея",0,536,0,0],["v","Бычьи туши в Пифийских храмах…",0,537,0,0],["v","А Эрота, царя над смертными,",0,538,0,0],["v","Ублажить, дитя Кипридино,",0,539,0,0],["v","Не хотим. Пусть ее теремов любви",0,540,0,1],["v","Он ключарь, но для нас он жестокий бог:",0,541,0,0],["v","Сеет смерть и проклятия,",0,542,0,0],["v","Куда ступит Эрот, Зевесов сын…",0,543,0,0],["str","Строфа II"],["v","Ярма не познавшая дева",0,544,0,0],["v","И брачного чуждая ложа",0,545,0,0],["v","В садах расцвела эхалийских…",0,550,0,1],["v","Но, крови и пламени полны,",0,550,0,0],["v","Дымятся палаты Еврита,",0,551,0,0],["v","И терем пылает царевны,",0,552,0,0],["v","И нимфу дрожащую сыну",0,552,0,0],["v","Алкмены под адские гимны",0,553,0,0],["v","Проклятий и смерти <span class=\"ch\" data-ch=\"afrodita\">Киприда</span><a class=\"nr\" href=\"#n-k21\" data-n=\"k21\" aria-label=\"Примечание 21\">21</a>",0,554,0,0],["v","Вручает для горького брака…",0,555,0,0],["str","Антистрофа II"],["v","Ограда священная Фивы,",0,555,0,0],["v","Диркеи кипящая пена,<a class=\"nr\" href=\"#n-k22\" data-n=\"k22\" aria-label=\"Примечание 22\">22</a>",0,556,0,0],["v","Вы ужасы миру о силе",0,557,0,0],["v","Могли бы <span class=\"ch\" data-ch=\"afrodita\">Киприды</span> поведать.",0,557,0,0],["v","Она, средь блистаний и громов",0,558,0,0],["v","Склонивши на брачное ложе",0,559,0,0],["v","Грядущую Вакхову матерь,<a class=\"nr\" href=\"#n-k23\" data-n=\"k23\" aria-label=\"Примечание 23\">23</a>",0,560,0,1],["v","В объятия кинула смерти,",0,561,0,0],["v","О, страшная сила и сладость!",0,562,0,0],["v","Пчела с ее медом и жалом!",0,563,0,0],["act","Действие второе","a3","II"],["scene","Явление шестое","s8",3,8],["sd","Те же без кормилицы. Во время последних слов хора слышится во дворце смятение. <span class=\"ch\" data-ch=\"fedra\">Федра</span> тревожно прислушивается и потом встает, идет к двери, останавливается и обращается к орхестре."],["sp","<span class=\"ch\" data-ch=\"fedra\">Федра</span>"],["v","Оставьте песни, жены… Я погибла.",0,564,0,0],["sp","Корифей"],["v","Что ж страшного в чертоге слышишь ты?",0,565,0,0],["sp","<span class=\"ch\" data-ch=\"fedra\">Федра</span>"],["v","Там голоса. Постойте, дайте слушать…",0,566,0,0],["sp","Корифей"],["v","Начало страшное… Молчу… Молчу.",0,567,0,0],["sp","<span class=\"ch\" data-ch=\"fedra\">Федра</span>"],["str","Строфа I"],["v","Ах… ах…",0,568,0,0],["v","Несчастная! Чего же ждать еще мне?",0,570,0,1],["sp","Хор"],["str","Строфа II"],["v","Что ты слышишь? Чей же голос,",0,571,0,0],["v","О любимая царица?",0,572,0,0],["v","Что тебя, скажи, смутило?",0,573,0,0],["v","Иль ты страшное узнала?",0,574,0,0],["sp","<span class=\"ch\" data-ch=\"fedra\">Федра</span>"],["v","Я говорю вам — я погибла… Шум",0,575,0,0],["v","Там, за стеной… вы слышите ль, как шумно?",0,576,0,0],["sp","Хор"],["str","Строфа III"],["v","Но ведь ты у самой двери.",0,577,0,0],["v","Иль сама узнать не хочешь?",0,578,0,0],["v","О, прислушайся ж, царица,",0,579,0,0],["v","Отчего кричат в чертоге?",0,580,0,1],["sp","<span class=\"ch\" data-ch=\"fedra\">Федра</span>"],["v","Сын наездницы там громы",0,581,0,0],["v","На мою служанку мечет…",0,582,0,0],["v","Пауза. Прислушивается.",0,583,0,0],["sp","Хор"],["str","Антистрофа III"],["v","Да, я слышу — только смутно;",0,584,0,0],["v","Разбери ж и мне скажи;",0,585,0,0],["v","До тебя из двери близкой",0,586,0,0],["v","Речи их ясней доходят.",0,587,0,0],["sp","<span class=\"ch\" data-ch=\"fedra\">Федра</span>"],["v","Я слышу ясно, как зовет ее",0,588,0,0],["v","Он своднею, предавшей господина.",0,590,1,1],["sp","Хор"],["str","Антистрофа II"],["v","Горе! Горе… дорогая.",0,591,0,0],["v","Предана ты — нет спасенья,",0,592,0,0],["v","Больше нет и тайны, Федра,",0,593,0,0],["v","И от друга ты погибла.",0,594,0,0],["sp","<span class=\"ch\" data-ch=\"fedra\">Федра</span>"],["str","Антистрофа I"],["v","Она меня сгубила… Мой недуг",0,595,0,0],["v","Ему она пересказала. Мне ж",0,596,0,0],["v","Она дала в лекарстве выпить яду.",0,597,0,0],["sp","Корифей"],["v","Но дальше что ж? Где выход ты найдешь?",0,598,0,0],["sp","<span class=\"ch\" data-ch=\"fedra\">Федра</span>"],["v","Или сама я знаю?.. Двери дома",0,599,0,0],["v","Аидова я вижу пред собою.",0,600,0,1],["sd","(Отходит к статуе <span class=\"ch\" data-ch=\"afrodita\">Киприды</span> и становится как бы под ее защиту.)"],["scene","Явление седьмое","s9",3,9],["sd","Из средних дверей выходит <span class=\"ch\" data-ch=\"ippolit\">Ипполит</span>. За ним, цепляясь за его одежду, насмерть перепуганная кормилица. <span class=\"ch\" data-ch=\"ippolit\">Ипполит</span>, кормилица, Федра, лица без речей."],["sp","<span class=\"ch\" data-ch=\"ippolit\">Ипполит</span>"],["v","Вы, светлые лучи!.. И ты, земля!..",0,601,0,0],["v","И это было сказано?.. О, ужас!..",0,602,0,0],["sp","<span class=\"ch\" data-ch=\"kormilitsa\">Кормилица</span>"],["v","Ах, тише, тише… Могут услыхать.",0,603,0,0],["sp","<span class=\"ch\" data-ch=\"ippolit\">Ипполит</span>"],["v","Я не могу молчать… Ведь это ж ужас…",0,604,0,0],["sp","<span class=\"ch\" data-ch=\"kormilitsa\">Кормилица</span>"],["dir","ловя его руку"],["v","Десницею могучей заклинаю…",0,605,0,0],["sp","<span class=\"ch\" data-ch=\"ippolit\">Ипполит</span>"],["v","Прочь, руки прочь… И выпусти мой плащ…",0,606,0,0],["sp","<span class=\"ch\" data-ch=\"kormilitsa\">Кормилица</span>"],["dir","бросаясь к его ногам и преграждая путь"],["v","У ног твоих, у ног молю пощады.",0,607,0,0],["sp","<span class=\"ch\" data-ch=\"ippolit\">Ипполит</span>"],["v","Какой? Ведь ты ж, по-твоему, права.",0,608,0,0],["sp","<span class=\"ch\" data-ch=\"kormilitsa\">Кормилица</span>"],["v","Огласки я боюсь. Пойми, огласки.",0,609,0,0],["sp","<span class=\"ch\" data-ch=\"ippolit\">Ипполит</span>"],["v","Прекрасного молва не оскорбит.",0,610,0,1],["sp","<span class=\"ch\" data-ch=\"kormilitsa\">Кормилица</span>"],["dir","приподнимаясь"],["v","Дитя мое, ты ж клялся, вспомни только…",0,610,0,0],["sp","<span class=\"ch\" data-ch=\"ippolit\">Ипполит</span>"],["v","Устами, да, — но сердце ни при чем.",0,611,0,0],["sp","<span class=\"ch\" data-ch=\"kormilitsa\">Кормилица</span>"],["v","Ужель друзей, дитя мое, погубишь?",0,612,0,0],["sp","<span class=\"ch\" data-ch=\"ippolit\">Ипполит</span>"],["v","Чур, чур меня! Неправый — мне не друг.",0,613,0,0],["sp","<span class=\"ch\" data-ch=\"kormilitsa\">Кормилица</span>"],["v","Кому ж прощать, дитя, коли не людям?",0,614,0,0],["sd","Пауза."],["sd","(<span class=\"ch\" data-ch=\"kormilitsa\">Кормилица</span> отходит к <span class=\"ch\" data-ch=\"fedra\">Федре</span>, но та молча, скрестивши руки, смотрит на <span class=\"ch\" data-ch=\"ippolit\">Ипполита</span> и не замечает ее. Тогда она подходит к хору, обмениваясь с хоревтами жестами удивления и страха.)"],["sp","<span class=\"ch\" data-ch=\"ippolit\">Ипполит</span>"],["v","О Зевс! Зачем ты создавал жену?",0,615,0,0],["v","И это зло с его фальшивым блеском",0,616,0,0],["v","Лучам небес позволил обливать?",0,617,0,0],["v","Иль для того, чтоб род людской продолжить,",0,618,0,0],["v","Ты обойтись без женщины не мог?",0,619,0,0],["v","Иль из своих за медь и злато храмов",0,620,0,1],["v","Иль серебро не мог бы сыновей",0,621,0,0],["v","Ты продавать, чего который стоит,",0,622,0,0],["v","Освободив жилища нам от жен?",0,623,0,0],["v","Что жены зло, мне доказать не трудно.",0,624,0,0],["v","Родной отец за дочерью, ее",0,625,0,0],["v","Взлелеявши, чужому человеку",0,626,0,0],["v","Приданое дает — освободи",0,627,0,0],["v","Его от дочки только. Муж, конечно,",0,628,0,0],["v","Отравленной украсив розой сад,",0,630,0,1],["v","Ей восхищен бывает. Точно куклу",0,631,0,0],["v","Иль алмаз фальшивый, он жену",0,632,0,0],["v","Старается оправить подороже.",0,633,0,0],["v","Но и мужей жена нищит, и только.",0,634,0,0],["v","И хорошо, кому попалось в дом<a class=\"nr\" href=\"#n-k25\" data-n=\"k25\" aria-label=\"Примечание 25\">25</a>",0,635,0,0],["v","Ничтожное творенье, чтоб ни злого,",0,636,0,0],["v","Ни доброго придумать не могла.",0,637,0,0],["v","Но умницы!.. Избави боже, если",0,640,0,1],["v","В ней на вершок побольше, чем в других,",0,640,0,0],["v","Ума, излишек этот <span class=\"ch\" data-ch=\"afrodita\">Афродите</span>",0,641,0,0],["v","На пользу лишь — коварством станет он.",0,642,0,0],["v","Напротив, та, которая природой",0,643,0,0],["v","Обижена жена, по крайней мере,",0,644,0,0],["v","На хитрости <span class=\"ch\" data-ch=\"afrodita\">Киприды</span> не пойдет",0,645,0,0],["v","Приспешниц — вот от жен подальше надо.",0,645,0,0],["v","Вы сторожить поставьте терема",0,646,0,0],["v","Зверей, когда хотите, да не этих",0,647,0,0],["v","Пособниц, зверь укусит, да не скажет,",0,648,0,0],["v","А то хозяйка козни мастерит,",0,649,0,0],["v","А нянюшка их по свету разносит…",0,650,0,1],["sd","(К хору, указывая на кормилицу.)"],["v","Не такова ль и эта тварь? Отца",0,650,0,0],["v","Священное она дерзнула ложе",0,651,0,0],["v","Мне, сыну, предлагать. Да после слов",0,652,0,0],["v","Таких — иди к источнику и уши",0,652,0,0],["v","Омой священной влагой. Если я",0,653,0,0],["v","В себе заразу чувствую от звука,",0,654,0,0],["v","От шума слов, так каково же сердцу",0,655,0,0],["v","От грязи их? Но я благочестив,",0,655,0,0],["v","И это вас теперь спасает, жены,",0,656,0,0],["v","Поверьте, все бы ваши я открыл",0,657,0,0],["v","Дела отцу, когда бы, как ребенок,",0,657,0,0],["v","Сковать уста себе я клятвой не дал.",0,658,0,0],["v","Простор теперь предоставляю вам,",0,659,0,0],["v","Пока <span class=\"ch\" data-ch=\"tesey\">Тесея</span> нет, и для признаний",0,660,0,1],["v","Я не открою губ. Но вместе с ним",0,660,0,0],["v","И я сюда вернусь — мне любопытно",0,661,0,0],["v","Вас с госпожой увидеть, как царя",0,662,0,0],["v","Вы будете встречать. Хотя образчик",0,662,0,0],["v","Твоей, раба, я наглости видал.",0,663,0,0],["sd","(Бросив боковой взгляд на <span class=\"ch\" data-ch=\"fedra\">Федру</span>.)"],["v","Так будьте же вы прокляты! Ни в веки",0,664,0,0],["v","Я не скажу, что ненавидеть женщин",0,664,0,0],["v","Сильнее невозможно, и меня",0,665,0,0],["v","Пускай зовут хоть взбалмошным, покуда",0,666,0,0],["v","Все те ж оне.",0,666,0,0],["v","О смертные, иль жен",1,666,0,0],["v","Исправьте нам, иль языку дозвольте",0,667,0,0],["v","Их укорять, а сердцу проклинать.",0,668,0,0],["sd","(Уходит в правую дверь.)"],["scene","Явление восьмое","s10",3,10],["sd","Без <span class=\"ch\" data-ch=\"ippolit\">Ипполита</span>."],["sp","<span class=\"ch\" data-ch=\"fedra\">Федра</span>"],["v","О, жребий жены!",0,668,0,0],["v","О, как над тобою не плакать?",0,669,0,0],["v","Где сила искусства?",0,670,0,1],["v","Где выход?",0,670,0,0],["v","О, как этим цепким объятьем",0,671,0,0],["v","Опутана я безнадежно!",0,671,0,0],["v","Уж мой приговор",0,672,0,0],["v","Написан. О солнце! О солнце!",0,672,0,0],["v","О матерь-земля!",0,673,0,0],["v","Куда я уйду от несчастья?",0,674,0,0],["v","Чем горе покрою?",0,674,0,0],["v","О жены! О жены!",0,675,0,0],["v","Иль бог мне поможет? Но кто же?..",0,675,0,0],["v","Иль вступится смертный в такое",0,676,0,0],["v","Позорное дело?.. На плечи",0,677,0,0],["v","Напала несносная тяжесть.",0,677,0,0],["v","И смерть, только смерть ее снимет…",0,678,0,0],["v","Меж женских, увы,",0,678,0,0],["v","Несчастнее нет моей доли!",0,679,0,0],["sp","Корифей"],["v","Увы! Увы! Посланницы искусство",0,680,0,1],["v","Не удалось. Ты в тяжком положенье…",0,680,0,0],["sp","<span class=\"ch\" data-ch=\"fedra\">Федра</span>"],["dir","кормилице"],["v","О худшая из жен… Друзей своих",0,681,0,0],["v","Не пощадить… Пускай отец небесный",0,682,0,0],["v","Тебя, огнем изранив, в порошок",0,683,0,0],["v","Потом сотрет. Что ж, я молчала, скажешь?",0,684,0,0],["v","Иль хитростям заранее твоим",0,685,0,0],["v","Позорного конца не предрекала?",0,686,0,0],["v","Позорного? Да, да. Для <span class=\"ch\" data-ch=\"fedra\">Федры</span> больше",0,687,0,0],["v","Почетной нет кончины. Но довольно.",0,688,0,0],["v","Теперь важнее дело. Гнев его",0,689,0,0],["v","Не пощадит, конечно, пред <span class=\"ch\" data-ch=\"tesey\">Тесеем</span>",0,690,0,1],["v","Болтливости твоей неосторожной,",0,690,0,0],["v","И речи, точно реки, потекут",0,691,0,0],["v","По всей земле постыдные. Проклятье ж",0,692,0,0],["v","Тебе и всем проклятие, кто рад",0,692,0,0],["v","С непрошеной готовностью и дерзко",0,693,0,0],["v","Служить своим измученным друзьям!",0,694,0,0],["sp","<span class=\"ch\" data-ch=\"kormilitsa\">Кормилица</span>"],["v","Ты не меня бранишь, а неудачу:",0,694,0,0],["v","Обида ум озлобленный мутит.",0,695,0,0],["v","О, у меня нашлись бы оправданья,",0,696,0,0],["v","Когда бы их ты слушала. Тебя",0,696,0,0],["v","Кто выкормил и вырастил, царица?",0,697,0,0],["v","Кто преданней служил тебе? Недуг",0,698,0,0],["v","Я исцелить хотела твой и гибну",0,698,0,0],["v","За то, что не сумела. А сумей,",0,699,0,0],["v","Из мудрых бы слыла теперь я мудрой.",0,700,0,1],["v","Ведь ум людей не то же ль, что успех?",0,700,0,0],["sp","<span class=\"ch\" data-ch=\"fedra\">Федра</span>"],["v","Изранила и диким пререканьем",0,701,0,0],["v","Мне рану бередишь. Иль это все?",0,702,0,0],["v","Вся правда? Все, что <span class=\"ch\" data-ch=\"fedra\">Федра</span> заслужила?",0,703,0,0],["sp","<span class=\"ch\" data-ch=\"kormilitsa\">Кормилица</span>"],["dir","подходя к <span class=\"ch\" data-ch=\"fedra\">Федре</span>"],["v","Постой. Пускай была я неправа.",0,704,0,0],["v","Но и теперь не все еще погибло.",0,705,0,0],["sp","<span class=\"ch\" data-ch=\"fedra\">Федра</span>"],["dir","с повелительным жестом"],["v","Нет, более ни слова! До сих пор",0,705,0,0],["v","Ты только зло нашептывала. Только",0,706,0,0],["v","Дурное начинала. Уходи",0,707,0,0],["v","К своим делам. Нам помощи не надо.",0,708,0,0],["v","Кормилица, плача, уходит налево в дверь.",0,709,0,0],["scene","Явление девятое","s11",3,11],["sd","Без кормилицы."],["sp","<span class=\"ch\" data-ch=\"fedra\">Федра</span>"],["dir","к хору"],["v","Вы ж, жены благородные Трезена,",0,710,0,1],["v","Не откажите мне в одном — уста",0,711,0,0],["v","Безмолвием окутать перед тайной.",0,712,0,0],["sp","Корифей"],["dir","обращаясь к <span class=\"ch\" data-ch=\"artemida\">Артемиде</span> и потом к <span class=\"ch\" data-ch=\"fedra\">Федре</span>"],["v","Я чистою богинею клянусь,",0,713,0,0],["v","Что твоего несчастия не выдам.",0,714,0,0],["sp","<span class=\"ch\" data-ch=\"fedra\">Федра</span>"],["v","О, будьте же вы счастливы! А я",0,715,0,0],["v","Еще имею выход, как сберечь",0,716,0,0],["v","Потомству имя доброе.",0,717,0,0],["v","Да он",1,717,0,0],["v","И для меня в моем несчастье лучше.",0,718,0,0],["v","О нет, я славной родины моей",0,719,0,0],["v","Не посрамлю и на показ <span class=\"ch\" data-ch=\"tesey\">Тесею</span>",0,720,0,1],["v","Позорного не вынесу клейма,",0,720,0,0],["v","Чтоб сохранить остаток жалкой жизни.",0,721,0,0],["sp","Корифей"],["v","Кого ж спасешь неисцелимым злом?<a class=\"nr\" href=\"#n-k26\" data-n=\"k26\" aria-label=\"Примечание 26\">26</a>",0,722,0,0],["sp","<span class=\"ch\" data-ch=\"fedra\">Федра</span>"],["v","Себя спасу. А как — увидишь после.",0,723,0,0],["sp","Корифей"],["v","Стыдись же слов таких.",0,724,0,0],["sp","<span class=\"ch\" data-ch=\"fedra\">Федра</span>"],["v","А ты стыдись",1,724,0,0],["v","Нас упрекать. Иль не <span class=\"ch\" data-ch=\"afrodita\">Киприде</span> я,",0,725,0,0],["v","Не этой жрице на алтарь сегодня",0,725,0,0],["v","Усладою паду? Мне горек был",0,726,0,0],["v","Любовный жребий, жены, но, страданьем",0,727,0,0],["v","Венчанная, я и другую смерть",0,728,0,0],["v","В своей таю. Есть муж. Из муки этой",0,729,0,0],["v","Смирения он вынесет урок:",0,730,0,1],["v","Один недуг, одна и кара будет.",0,730,0,0],["v","Уходит в среднюю дверь, служанки уносят ложе.",0,731,0,0],["scene","Второй музыкальный антракт","s12",3,12],["sp","Хор"],["str","Строфа I"],["v","О, если б укрыться могла я",0,732,0,0],["v","Туда, в эти темные выси,",0,733,0,0],["v","О, если б, велением бога,",0,733,0,0],["v","Меж птицами вольною птицей",0,734,0,0],["v","Вилась я. Туда бы стрелой,",0,735,0,0],["v","Туда б я хотела, где море",0,736,0,0],["v","Синеет, к брегам Эридана,",0,736,0,0],["v","Где в волны пурпурные, блеском",0,737,0,0],["v","Отцовским горящие волны,",0,738,0,0],["v","Несчастные девы не слезы",0,739,0,0],["v","В печали по брате погибшем,",0,740,0,1],["v","Янтарное точат сиянье.",0,741,0,0],["str","Антистрофа I"],["v","Туда, где в садах налилися —",0,742,0,0],["v","Мечты или песни поэтов —",0,743,0,0],["v","Плоды Гесперид золотые,",0,744,0,0],["v","Туда, где на грани волшебной",0,745,0,0],["v","Плывущей предел положили",0,746,0,0],["v","Триере — морей промыслитель",0,747,0,0],["v","И мученик небодержавный,",0,748,0,0],["v","Туда, где у ложа Кронида",0,749,0,0],["v","Своею нетленной струею",0,750,0,1],["v","Один на всю землю источник,",0,750,0,0],["v","Златясь и шумя, животворный<a class=\"nr\" href=\"#n-k27\" data-n=\"k27\" aria-label=\"Примечание 27\">27</a>",0,751,0,0],["v","Для радости смертных пробился…",0,752,0,0],["str","Строфа II"],["v","От брегов родимых Крита",0,753,0,0],["v","И от мирной сени отчей",0,753,0,0],["v","За ладьею белокрылой",0,754,0,0],["v","С шумной жалобой недаром",0,755,0,0],["v","Волны пенные бежали:",0,756,0,0],["v","Не нашла невеста мира",0,756,0,0],["v","В этом браке.",0,757,1,0],["v","С Крита ль только птицы злые",0,758,1,0],["v","Вашу свадьбу провожали.",0,759,1,0],["v","Или встретили в Афинах,",0,760,1,1],["v","У Мунихия, когда вы,",0,760,1,0],["v","В волны новые тяжелый",0,761,1,0],["v","Бросив якорь, на священный",0,762,1,0],["v","Брег Паллады выходили?",0,763,1,0],["str","Антистрофа II"],["v","Там мучительным недутом",0,763,0,0],["v","Грешной страсти поразила,",0,764,0,0],["v","В оправданье знаков черных,<a class=\"nr\" href=\"#n-k28\" data-n=\"k28\" aria-label=\"Примечание 28\">28</a>",0,765,0,0],["v","Золотая <span class=\"ch\" data-ch=\"afrodita\">Афродита</span>",0,766,0,0],["v","Душу нежную царицы:",0,766,0,0],["v","И ужасных испытаний",0,767,0,0],["v","Не снести ей!",0,768,0,0],["v","Вот идет поспешно в терем,",0,769,1,0],["v","Вот рука на белой шее",0,770,1,1],["v","Петлю вяжет и не дрогнет.",0,770,1,0],["v","Страшен демон ненавистный,",0,771,1,0],["v","И, спасая честь, царица",0,772,1,0],["v","Из души своей свободной",0,773,1,0],["v","Жало страсти вынимает.",0,774,1,0],["act","Действие третье","a4","III"],["scene","Явление десятое","s13",4,13],["sp","<span class=\"ch\" data-ch=\"kormilitsa\">Кормилица</span>"],["dir","за сценой"],["v","Ай… ай…",0,775,0,0],["v","Сюда! Сюда! Скорее все, кто может:",0,776,0,0],["v","Повесилась Тесеева царица.",0,777,0,0],["sp","Корифей"],["v","Увы! Увы! Все кончено. Висит",0,778,0,0],["v","Она в ужасной петле. <span class=\"ch\" data-ch=\"fedra\">Федры</span> нет.",0,779,0,0],["sp","<span class=\"ch\" data-ch=\"kormilitsa\">Кормилица</span>"],["dir","за сценой"],["v","Скорей же… О, скорей… И нож острей,",0,780,0,1],["v","Разрезать эту петлю… Помогите…",0,781,0,0],["sd","Одна из хора"],["v","Что делать нам, подруги? Во дворец",0,782,0,0],["v","Пойдем ли вынимать ее из петли?",0,783,0,0],["sd","Другая из хора"],["v","Зачем? Иль нет там молодых рабынь?",0,784,0,0],["v","Кто без толку хлопочет, не поможет.",0,785,0,0],["sp","<span class=\"ch\" data-ch=\"kormilitsa\">Кормилица</span>"],["dir","за сценой, с плачем"],["v","Снимите ж хоть ее… не дышит больше…<a class=\"nr\" href=\"#n-k29\" data-n=\"k29\" aria-label=\"Примечание 29\">29</a>",0,786,0,0],["v","О, горькая палат охрана мужних.",0,787,0,0],["sp","Корифей"],["v","Сомненья нет… Скончалась… Тело там",0,788,0,0],["v","Уж на одре печальном полагают…",0,789,0,0],["scene","Явление одиннадцатое","s14",4,14],["sd","<span class=\"ch\" data-ch=\"tesey\">Тесей</span> (с левой стороны). Он увенчан лавром. За ним свита."],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["dir","сначала оглядывается на запертую дверь, ищет, к кому бы обратиться, потом, увидев хор —"],["v","Гей, женщины… Тут был какой-то крик…",0,790,0,1],["v","Неясный плач рабынь из зал дворцовых",0,791,0,0],["v","Издалека до слуха долетел.",0,792,0,0],["v","А здесь царя, узревшего святыню,<a class=\"nr\" href=\"#n-k30\" data-n=\"k30\" aria-label=\"Примечание 30\">30</a>",0,793,0,0],["v","И у дверей покинутых палат",0,794,0,0],["v","Ничей привет не встретил… Иль с Питфеем",0,795,0,0],["v","Что новое случилось, престарелым?",0,796,0,0],["sp","Корифей"],["v","Удар судьбы, <span class=\"ch\" data-ch=\"tesey\">Тесей</span>. Но не старик,",0,797,0,0],["v","А яркий, царь, погас здесь жизни светоч.",0,798,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","Увы! Увы! Не из детей же кто?",0,799,0,0],["sp","Корифей"],["v","Они живут — но матери не видят.",0,800,0,1],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","Что говоришь? Жена… Но как? Но как?",0,801,0,0],["sp","Корифей"],["v","От собственной руки, в ужасной петле.",0,802,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","В тоске, скажи, иль жребий оковал?",0,803,0,0],["sp","Корифей"],["v","Мы знаем то, что слышал ты, и только…",0,804,0,0],["v","И сами мы недавно здесь, <span class=\"ch\" data-ch=\"tesey\">Тесей</span>.",0,805,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","О, горе мне… На что ж и лавры эти",0,806,0,0],["v","На волосах?",0,807,0,0],["sd","(Срывает и бросает их.)"],["v","Не праздники справлять",0,808,4,0],["v","Придется здесь <span class=\"ch\" data-ch=\"tesey\">Тесею</span>… Гей, живее,",0,809,0,0],["v","Рабы, отбить запоры у ворот",0,810,0,0],["v","И настежь их!.. Пускай достойной плача",0,811,0,0],["v","Картиной я насыщу взор, — жены",0,825,0,1],["v","Я видеть труп хочу, себе на горе…",0,810,0,1],["sd","Рабы отбивают внутренний запор дверей. Широко распахнутые, они показывают внутренность дома. На носилках труп <span class=\"ch\" data-ch=\"fedra\">Федры</span>. Около и за ним толпятся служанки."],["scene","Явление двенадцатое","s15",4,15],["v","<span class=\"ch\" data-ch=\"tesey\">Тесей</span> и свита около мертвой <span class=\"ch\" data-ch=\"fedra\">Федры</span>.",0,810,0,0],["scene","Сцена плача","s16",4,16],["sp","Хор"],["dir","обращаясь к телу <span class=\"ch\" data-ch=\"fedra\">Федры</span>"],["v","Увы! Увы! Несчастная… О жребий,",0,811,0,0],["v","О злодеяние и ты,",0,812,0,0],["v","О мука, вы сгубили целый дом…",0,812,0,0],["v","О дерзость, о натиск безумный",0,813,0,0],["v","На жизнь, на собственную жизнь.",0,814,0,0],["v","Кто смел, скажите, кто смел",0,814,0,0],["v","На голову эту",0,815,0,0],["v","Покров погребального мрака накинуть?",0,816,0,0],["v","Кто смел?",0,816,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["str","Строфа"],["v","О, муки!.. О, город!.. Но нет,",0,817,0,0],["v","Нет горше, подъятых <span class=\"ch\" data-ch=\"tesey\">Тесеем</span>,",0,818,0,0],["v","О, тяжко, так тяжко на плечи",0,818,0,0],["v","Обрушился жребий, увы мне!",0,819,0,0],["v","То демона скрытая метка?",0,820,0,1],["v","Иль тайная точит нас язва?",0,821,0,0],["v","Не море ли бедствий темнеет?",0,822,0,0],["v","Кружат меня волны — не выплыть,",0,823,0,0],["v","И хлещут, наверх не пускают.",0,824,0,1],["v","Твоя ж, о жена, в каких же словах",0,826,0,1],["v","Предсмертная мука, скажи мне, сокрылась?",0,827,0,0],["v","Ты легче, чем птица из плена",0,828,0,0],["v","В эфире, в Аиде исчезла.",0,829,0,0],["v","О, жребий, о, жребий плачевный!",0,830,0,1],["v","Мне предок оставил пятно, —",0,831,0,0],["v","Слезами его замываю.",0,832,0,0],["sp","Корифей"],["v","Не первый ты подругу, царь, оплакал,",0,833,0,0],["v","И не один ты дивную терял…",0,834,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["str","Антистрофа"],["v","Туда я… в подземную ночь",0,835,0,0],["v","Хочу, и в могиле хочу я",0,836,0,0],["v","Без солнца лежать, потому что",0,837,0,0],["v","Ты больше меня не обнимешь,",0,838,0,0],["v","Мертва ты… Я ж тени бледнее…",0,839,0,0],["v","О, как эти страшные мысли,",0,840,0,1],["v","Жена, в твою душу проникли?",0,841,0,0],["v","О нет, не таитесь, рабыни:",0,842,0,0],["v","Иль чужды душою вы дому?..",0,843,0,0],["v","О, горе, и ты, о зрелище мук!",0,844,0,0],["v","Умом не охватишь, не вынесешь сердцем.",0,845,0,0],["v","Без матери дети — и в доме",0,846,0,0],["v","Хозяйки не стало. Меня же,",0,847,0,0],["v","Меня ж на кого покидаешь,",0,848,0,0],["v","О лучшая в ярких лучах,",0,850,0,1],["v","О лучшая в лунном мерцанье?",0,850,0,0],["sp","Хор"],["v","Несчастный, несчастнейший муж!",0,851,0,0],["v","Ты, бедами дом осажденный!",0,852,0,0],["v","Над горем твоим, властелин,",0,852,0,0],["v","Слезами склонились мои орошенные веки,",0,853,0,0],["v","Но ужас холодных предчувствий",0,854,0,0],["v","В груди и давней и больней.",0,855,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","Ба… Погляди…",0,855,0,0],["v","Ведь белая рука ее застыла,",0,856,0,0],["v","Письмо сжимая… Или новых мук",0,857,0,0],["v","Оно несет нам бремя, или в нем",0,857,0,0],["v","Вдовцу или сиротам свой завет",0,858,0,0],["v","Она перед разлукой написала?",0,859,0,0],["v","Нет, бедная, в оставленный тобой",0,860,0,1],["v","Уж не войдет чертог жена другая.",0,860,0,0],["v","Покойно спи…",0,861,0,0],["sd","(Делая шаг, направляясь к телу.)"],["v","О да, я узнаю",0,862,4,0],["v","Кольца печать усопшей золотую…",0,862,0,0],["v","Мгновение и, складень растворив,",0,863,0,0],["v","Последних строк ее узнаю тайну.",0,864,0,0],["sd","(Подходит к телу и, разжав руку <span class=\"ch\" data-ch=\"fedra\">Федры</span>, вынимает складень. Пока он распечатывает его и читает — )"],["sp","Хор"],["v","О, горе, о, горе…",0,865,2,0],["v","То новый удар",0,865,1,0],["v","Нам демон готовит… Увы…",0,866,1,0],["v","Жизнь цену для меня теряет… Это будет,",0,867,0,0],["v","Я чувствую, удар смертельный. Пусть же",0,867,0,0],["v","И на меня он падает:",0,868,1,0],["v","В обломках на земле",0,869,1,0],["v","Моих царей лежит былое счастье…<a class=\"nr\" href=\"#n-k32\" data-n=\"k32\" aria-label=\"Примечание 32\">32</a>",0,870,0,1],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","О, ужас!.. Омерзение и ужас!..",0,871,0,0],["sp","Корифей"],["v","Но что? скажи… Коли я смею знать!",0,872,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","О, к небу вопиют,",0,873,1,0],["v","О, к небу те немые вопиют",0,874,1,0],["v","Об ужасе неслыханном слова.",0,875,1,0],["v","Куда уйти? Нет… Это слишком… Эти",0,880,0,1],["v","В какой-то адский хор смешались строки.",0,880,0,0],["sp","Корифей"],["v","Увы! Увы!",0,881,1,0],["v","О, новых бед ужасное начало!",0,882,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","О нет, мои уста",0,882,1,0],["v","Таить не смеют этой язвы страшной,",0,883,0,0],["v","Уродства этого, что и назвать мерзит…",0,884,0,0],["v","Пусть полумертвого добьют они. Но знай…",0,884,0,0],["v","Но знай, земля отцов,",0,885,0,0],["v","Сын, Ипполит, на ложе посягнул",0,886,0,0],["v","Отцовское, не устыдился Зевса",0,886,0,0],["v","Очей. О Посидон, о мой отец!",0,887,0,0],["v","Три за тобой желания, и вот",0,888,0,0],["v","Желанье первое: пускай мой сын",0,888,0,0],["v","Не доживет до этой ночи, если",0,889,0,0],["v","Твоим должны мы верить обещаньям.",0,890,0,1],["v","Из хора вырывается крик ужаса.",0,890,0,0],["sp","Корифей"],["v","Ради богов! Возьми назад слова…",0,891,0,0],["v","Раскаешься ты, царь, в своем желанье.",0,892,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","Нет, никогда. И из страны его",0,893,0,0],["v","Я изгоню. Готовы оба кубка",0,894,0,0],["v","С отравою. Пусть жалобу мою",0,895,0,0],["v","Пучины царь услышит и сегодня ж",0,895,0,0],["v","Его сошлет в Аид, иль, осужден,",0,896,0,0],["v","До вечера, как нищий, он скитанья",0,897,0,0],["v","Свои начнет велением моим…",0,898,0,0],["sp","Корифей"],["v","Смотри: твой сын; он вовремя, владыка.",0,899,0,0],["v","Безумный гнев покинь и осени",0,900,0,1],["v","Свой дом иным и набожным желаньем.<a class=\"nr\" href=\"#n-k34\" data-n=\"k34\" aria-label=\"Примечание 34\">34</a>",0,901,0,0],["scene","Явление тринадцатое","s17",4,17],["sd","Те же и <span class=\"ch\" data-ch=\"ippolit\">Ипполит</span> в сопровождении небольшой свиты (справа)."],["sp","<span class=\"ch\" data-ch=\"ippolit\">Ипполит</span>"],["dir","еще не видя трупа"],["v","На голос твой отчаянный, отец,",0,902,0,0],["v","Я прихожу… Из-за чего он, знать",0,903,0,0],["v","Хотел бы…",0,904,0,0],["sd","(Видит труп <span class=\"ch\" data-ch=\"fedra\">Федры</span> и отшатывается.)"],["v","Га… Что вижу?.. Тело",0,905,4,0],["v","Твоей жены?.. Как это непонятно,",0,906,0,0],["v","Ведь я ж сейчас расстался с ней, — была",0,907,0,0],["v","Она совсем здорова. Этот мертвый",0,908,0,0],["v","Покой ее так странен… Как же смерть",0,909,0,0],["v","Ты объяснить бы мог, отец?.. И что же",0,910,0,1],["v","Ты все молчишь? Иль думаешь беду",0,910,0,0],["v","Томительной развеять немотою?",0,911,0,0],["v","Коль тайна жжет желанием сердца,",0,912,0,0],["v","В несчастии огонь ее живее,",0,913,0,0],["v","И ты не прав, скрывая от друзей…",0,914,0,0],["v","Нет, больше, чем друзей… свои печали.",0,915,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["dir","не глядя на сына"],["v","О, суета! О, жалкий род слепцов!",0,915,0,0],["v","Нет хитростей, каких бы допытаться",0,916,0,0],["v","Ты не сумел, упорный человек.",0,917,0,0],["v","Десятками ты их считаешь тысяч.",0,918,0,0],["v","Но обучить того, в ком смысла нет,",0,919,0,0],["v","Усовестить мошенника возьмешься ль?..",0,920,0,1],["sp","<span class=\"ch\" data-ch=\"ippolit\">Ипполит</span>"],["v","Такой учитель стал бы знаменит,<a class=\"nr\" href=\"#n-k33\" data-n=\"k33\" aria-label=\"Примечание 33\">33</a>",0,871,0,0],["v","Свой ум в чужие головы влагая.<a class=\"nr\" href=\"#n-k31\" data-n=\"k31\" aria-label=\"Примечание 31\">31</a>",0,822,0,0],["v","Но, может быть, мы бросим шутки, царь:",0,773,0,0],["v","Несчастие, боюсь, мутит твой разум.",0,724,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["dir","продолжает, не глядя на него"],["v","О, если бы хотя малейший знак",0,675,0,0],["v","Имели мы, но верный, чтобы друга",0,625,0,0],["v","От недруга и лживые слова<a class=\"nr\" href=\"#n-k24\" data-n=\"k24\" aria-label=\"Примечание 24\">24</a>",0,576,0,0],["v","От истинных мы сразу отличали…",0,527,0,0],["v","Два голоса пускай бы человек",0,478,0,0],["v","Имел — один, особенный, для правды,",0,429,0,0],["v","Другой — какой угодно. Ведь тогда",0,380,0,0],["v","Разоблачить всегда бы ложь могли мы,",0,330,0,1],["v","Игралищем людей не становясь.",0,331,0,0],["sp","<span class=\"ch\" data-ch=\"ippolit\">Ипполит</span>"],["v","Иль кто-нибудь из близких пред тобой",0,332,0,0],["v","Оклеветал меня? Иль и невинность",0,333,0,0],["v","От низости не ограждает нас?..",0,334,0,0],["v","Я с толку сбит. И странные намеки",0,335,0,0],["v","Твои, отец, измучили меня.",0,336,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","О, до чего ж дойдешь ты, род людской?",0,337,0,0],["v","Иль грани нет у дерзости?.. Препоны",0,338,0,0],["v","У наглости?.. Рожденьем человек",0,339,0,0],["v","Приподнимай на палец только гребень",0,340,0,0],["v","У дерзости, чтобы отца возрос",0,341,0,0],["v","Хитрее сын, а внук хитрее сына,",0,342,0,0],["v","И на земле не хватит места скоро",0,343,0,0],["v","Преступникам. И к этой прибавлять",0,940,0,1],["v","Богам бы не пришлось вторую землю.",0,941,0,0],["sd","(К хору и окружающим.)"],["v","Смотрите все… Вот сын мой, опозорил",0,942,0,0],["v","Он ложе мне, — и мертвая его,",0,943,0,0],["v","Как низкого злодея, уличает.",0,944,0,0],["sd","Ипполит, бледнея, опускает глаза, замечая в руках отца письмо."],["sd","(<span class=\"ch\" data-ch=\"ippolit\">Ипполиту</span>.)"],["v","Что не глядишь? Коль язвою твоей",0,945,0,0],["v","Я заражен, ужели глаз бояться",0,946,0,0],["v","Твоих отцу.",0,947,0,0],["v","Так вот он, этот муж,",1,947,0,0],["v","Отмеченный богами, их избранник,",0,948,0,0],["v","Невинности и скромности фиал…",0,949,0,0],["v","Когда б твоим рассказам шарлатанским",0,950,0,1],["v","Поверил я, — я не богов бы чтил,",0,950,0,0],["v","А лишь невежд в божественных одеждах.",0,951,0,0],["v","Ты чванишься, что в пищу не идет",0,951,0,0],["v","Тебе ничто дышавшее, и плутни",0,952,0,0],["v","Орфеевым снабдил ты ярлыком.<a class=\"nr\" href=\"#n-k35\" data-n=\"k35\" aria-label=\"Примечание 35\">35</a>",0,953,0,0],["v","О, ты теперь свободен — к посвященным",0,953,0,0],["v","На праздники иди и пылью книг",0,954,0,0],["v","Пророческих любовно упивайся:",0,955,0,0],["v","Ты больше не загадка.",0,955,0,0],["v","Но таких,",1,955,0,0],["v","Пожалуйста, остерегайтесь, люди,",0,956,0,0],["v","Позорное таят под благочестъем",0,956,0,0],["v","Они искусство.",0,957,0,0],["v","Это только труп…",1,957,0,0],["v","Но от того тебе теперь не легче,",0,958,0,0],["v","Из низких самый низкий. Уличен",0,958,0,0],["v","Ты мертвою. Ты уничтожен ею.",0,959,0,0],["v","Перед ее судом что значат клятвы,",0,960,0,1],["v","Свидетели и вся шумиха слов?",0,960,0,0],["v","Иль скажешь ты, что был ей ненавистен,",0,961,0,0],["v","Что незаконный сын, при сыновьях",0,962,0,0],["v","Законных, им всегда помехой будет?",0,963,0,0],["v","Но не безумно ль было б отдавать",0,963,0,0],["v","Дыхание свое и счастье ближних",0,964,0,0],["v","Взамен твоих страданий?.. Это ложь…",0,965,0,0],["v","Иль чувственность царит не та же, скажешь,",0,966,0,0],["v","Над нами, что над женскою душой?",0,966,0,0],["v","Мне юноши известны, что не могут",0,967,0,0],["v","Наплыва страсти выдержать, — любой",0,968,0,0],["v","Слабей они девчонки. Только пол",0,969,0,0],["v","Спасает их от осужденья.",0,970,0,1],["v","Впрочем,",1,970,0,0],["v","Не лишнее ль все это? Здесь лежит",0,970,0,0],["v","Свидетель неподвижный, но надежный:",0,971,0,0],["v","Ты осужден. Немедленно покинешь",0,972,0,0],["v","Трезен. Священная земля Афин",0,973,0,0],["v","И все моей державы страны будут",0,974,0,0],["v","Отныне для тебя закрыты. Если б",0,975,0,0],["v","Тебя теперь простил я, Ипполит,",0,975,0,0],["v","И Синис бы, грабитель придорожный,<a class=\"nr\" href=\"#n-k36\" data-n=\"k36\" aria-label=\"Примечание 36\">36</a>",0,976,0,0],["v","Пожалуй бы, явился и сказал,",0,977,0,0],["v","Что я его убийством только хвастал,",0,978,0,0],["v","И скалы бы Скиронские тогда",0,979,0,0],["v","Грозы моей не стали больше славить.",0,980,0,1],["sp","Корифей"],["v","О, счастье, ты непрочно на земле:",0,980,0,0],["v","Твои колонны гордые во прахе.",0,981,0,0],["sp","<span class=\"ch\" data-ch=\"ippolit\">Ипполит</span>"],["v","Твоей души, отец, слепая страсть",0,982,0,0],["v","И гнев ее тяжелый оставляют",0,982,0,0],["v","Глубокий след в уме — не оттого,",0,983,0,0],["v","Чтоб был ты прав, однако.",0,984,0,0],["v","К сожаленью,",1,984,0,0],["v","Я склонности не чувствую в толпе",0,985,0,0],["v","Оправдывать себя и, вероятно,",0,985,0,0],["v","В своем кругу сумел бы доказать",0,986,0,0],["v","Ясней твою ошибку. И не так ли",0,987,0,0],["v","Нередко наш страдает тонкий слух",0,987,0,0],["v","От музыки, которой рукоплещет",0,988,0,0],["v","Толпа? Увы… Пред горшею бедой",0,989,0,0],["v","О меньшей мы позабываем. Вижу, —",0,990,0,1],["v","Завесу с уст приходится поднять.",0,990,0,0],["v","Начну с того же я, с чего искусно",0,991,0,0],["v","Ты начал речь. Оставь без возраженья",0,992,0,0],["v","Я первые слова — и я погиб.",0,992,0,0],["v","Взгляни вокруг на землю, где ступает",0,993,0,0],["v","Твоя нога, на солнце, что ее",0,994,0,0],["v","Живит, и не найдешь души единой",0,995,0,0],["v","Безгрешнее моей, хотя бы ты",0,995,0,0],["v","И спорил, царь. Богов я чтить умею,",0,996,0,0],["v","Живу среди друзей, и преступлений",0,997,0,0],["v","Бегут друзья мои. И стыдно им",0,997,0,0],["v","Других людей на злое наводить",0,998,0,0],["v","Или самим прислуживать пороку;",0,999,0,0],["v","Высмеивать друзей, пусть налицо",0,1000,0,1],["v","Они иль нет, я не умею. Тот же",0,1000,0,0],["v","Для них я друг. Ты упрекал меня",0,1001,0,0],["v","В страстях, отец, — нет, в этом я не грешен:",0,1002,0,0],["v","Я брака не познал и телом чист.",0,1003,0,0],["v","О нем я знаю то лишь, что услышал",0,1004,0,0],["v","Да на картинах видел. Да и тех",0,1005,0,0],["v","Я не люблю разглядывать. Душа",0,1005,0,0],["v","Стыдливая мешает.",0,1006,0,0],["v","Если скромность",1,1006,0,0],["v","В невинности тебя не убедит,",0,1007,0,0],["v","Так объясни ж, отец, каким же мог",0,1008,0,0],["v","Я развратиться способом. Иль <span class=\"ch\" data-ch=\"fedra\">Федра</span>",0,1009,0,0],["v","Такой уже неслыханной красы?",0,1010,0,1],["v","Иль у меня была надежда с ложем",0,1010,0,0],["v","На твой престол, ты скажешь? Но ведь это",0,1011,0,0],["v","Безумие бы было, коль не глупость.",0,1012,0,0],["v","Иль быть царем так сладостно для тех,",0,1013,0,0],["v","Кто истинно разумен? Ой, смотри,",0,1014,0,0],["v","Здоров ли ум, коли корона манит.",0,1015,0,0],["v","Я первым быть меж эллинов горел",0,1015,0,0],["v","На играх лишь, а в государстве, право ж,",0,1016,0,0],["v","И на втором нам месте хорошо…",0,1017,0,0],["v","Средь избранных, конечно. Там досуг,",0,1018,0,0],["v","Да и в глаза опасность там не смотрит,",0,1019,0,0],["v","А это слаще, царь, чем твой престол.",0,1020,0,1],["v","Теперь ты все уж знаешь. За себя",0,1020,0,0],["v","Такого же другого, к сожаленью,",0,1021,0,0],["v","Я не могу подставить, чтоб порукой",0,1022,0,0],["v","Тебе служил. Пред <span class=\"ch\" data-ch=\"fedra\">Федрою</span> живой",0,1023,0,0],["v","Мне также спор заказан. Ты легко бы",0,1023,0,0],["v","Нашел тогда виновных. А теперь",0,1024,0,0],["v","Хранителем клянусь тебе я клятвы",0,1025,0,0],["v","И матерью-землей, что никогда",0,1026,0,0],["v","Жены твоей не трогал, что ее",0,1026,0,0],["v","Я не желал и что о ней не думал.",0,1027,0,0],["v","И пусть умру, бесславно и покрытый",0,1028,0,0],["v","Позорным именем, ни в море я,",0,1029,0,0],["v","Ни на земле пускай успокоенья",0,1030,0,1],["v","И мертвый не найду… коль это ложно…",0,1030,0,0],["v","Замучена ли страхом, умерла",0,1031,0,0],["v","От собственной руки она, не знаю",0,1032,0,0],["v","И больше говорить не смею. Но",0,1033,0,0],["v","Неправая из дела вышла чистой,",0,1034,0,0],["v","А чистого и правда не спасла.",0,1035,0,0],["sp","Корифей"],["v","Ты опроверг отлично обвиненье,",0,1035,0,0],["v","И клятвою ты истину венчал.",0,1036,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","Смотрите-ка. Вот тактика… Сначала",0,1037,0,0],["v","Срамил отца, а после гнев его",0,1038,0,0],["v","Смирением уступчивым и лживым",0,1039,0,0],["v","Пытается, как маг, заворожить.",0,1040,0,1],["sp","<span class=\"ch\" data-ch=\"ippolit\">Ипполит</span>"],["v","Я одному, отец, теперь дивлюсь —",0,1041,0,0],["v","Изгнанию. Зачем не смерти ищешь?",0,1042,0,0],["v","Будь на твоем я месте, так обидчик",0,1043,0,0],["v","Казнен бы был за честь моей жены.",0,1044,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","О, это слишком мягко, сын мой. Казни",0,1045,0,0],["v","Немедленной от нас себе не жди.<a class=\"nr\" href=\"#n-k37\" data-n=\"k37\" aria-label=\"Примечание 37\">37</a>",0,1046,0,0],["v","Преступнику конец поспешный — милость.",0,1047,0,0],["v","Нет, ты, вдали от родины скитаясь,",0,1048,0,0],["v","Вымаливая хлеб, но будешь жить.",0,1050,0,1],["sp","<span class=\"ch\" data-ch=\"ippolit\">Ипполит</span>"],["v","О, небо! Или срока оправдаться,",0,1051,0,0],["v","Или угла покуда мне не дашь?",0,1052,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","За Понтом бы — когда бы мог, за гранью",0,1053,0,0],["v","Атлантовой. Ты мерзок мне, пойми.<a class=\"nr\" href=\"#n-k38\" data-n=\"k38\" aria-label=\"Примечание 38\">38</a>",0,1054,0,0],["sp","<span class=\"ch\" data-ch=\"ippolit\">Ипполит</span>"],["v","Как? без суда? без клятвы? без допроса?",0,1055,0,0],["v","И даже без гаданий — приговор?",0,1056,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","Письмо — твоя улика, и не нужно",0,1057,0,0],["v","Тут жребия. А птицы в небесах<a class=\"nr\" href=\"#n-k39\" data-n=\"k39\" aria-label=\"Примечание 39\">39</a>",0,1058,0,0],["v","На этот раз меня не занимают.",0,1059,0,0],["sp","<span class=\"ch\" data-ch=\"ippolit\">Ипполит</span>"],["v","О боги! Уст ужели и теперь",0,1060,0,1],["v","Не разрешите мне? Ведь эта клятва",0,1060,0,0],["v","Мне стоит жизни… Нет… я не хочу…",0,1061,0,0],["v","Ведь этот грех мне не вернул бы веры.",0,1062,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","О лицемер! Ты изведешь меня…",0,1063,0,0],["v","Вон из дому без всяких промедлений!",0,1064,0,0],["sp","<span class=\"ch\" data-ch=\"ippolit\">Ипполит</span>"],["v","Куда ж? О, горе! Кто ж откроет дверь",0,1065,0,0],["v","Изгнаннику с таким ярмом позорным?",0,1066,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","А как узнать? И соблазнитель жен",0,1067,0,0],["v","Иным мужьям бывает милым гостем.",0,1068,0,0],["sp","<span class=\"ch\" data-ch=\"ippolit\">Ипполит</span>"],["v","Так низко пасть пред миром, пред тобой…",0,1069,0,0],["v","Да кто же я?.. Сжимают горло слезы.",0,1070,0,1],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","Не поздно ль ты разнежился? Пока",0,1071,0,0],["v","Преступником ты не был — было плакать.",0,1072,0,0],["sp","<span class=\"ch\" data-ch=\"ippolit\">Ипполит</span>"],["v","Вы, стены, камни, вы заговорите!",0,1073,0,0],["v","Скажите же ему, что я невинен.",0,1074,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","Ссылаешься ты тонко на немых",0,1075,0,0],["v","Свидетелей",0,1076,0,0],["sd","(показывая на труп)"],["v","вот и еще один.",0,1077,4,0],["sp","<span class=\"ch\" data-ch=\"ippolit\">Ипполит</span>"],["v","Когда бы сам я встретился с собой,",0,1078,0,0],["v","Над этою бы я заплакал мукой.",0,1079,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","Да, сам себе ты был всегда кумир;",0,1080,0,1],["v","Родителей бы лучше почитал ты.",0,1080,0,0],["sp","<span class=\"ch\" data-ch=\"ippolit\">Ипполит</span>"],["v","О мать моя… О, горькое рожденье,",0,1081,0,0],["v","Внебрачное! Не дай бог никому.<a class=\"nr\" href=\"#n-k40\" data-n=\"k40\" aria-label=\"Примечание 40\">40</a>",0,1082,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","Гей! Взять его.",0,1083,0,0],["sd","(Слугам.)"],["v","Вы не слыхали разве,",0,1084,4,0],["v","Что приговор над ним произнесен?",0,1085,0,0],["sp","<span class=\"ch\" data-ch=\"ippolit\">Ипполит</span>"],["v","Беда тому, кто до меня коснется.",0,1086,0,0],["sd","(<span class=\"ch\" data-ch=\"tesey\">Тесею</span>.)"],["v","Душа горит, так сам и изгоняй.",0,1087,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","И сделаю… с ослушником. Нимало",0,1088,0,0],["v","Его при том, поверь, не сожалея.",0,1089,0,0],["sd","(Уходит со стражей в среднюю дверь, которая за ними запирается.)"],["scene","Явление четырнадцатое","s18",4,18],["sd","Те же без <span class=\"ch\" data-ch=\"tesey\">Тесея</span>."],["sp","<span class=\"ch\" data-ch=\"ippolit\">Ипполит</span>"],["v","Да, решено, и крепко. Есть ли мука",0,1090,0,1],["v","Сильнее той, когда ты знаешь все",0,1090,0,0],["v","И ничего открыть другим не можешь?",0,1091,0,0],["sd","(К статуе <span class=\"ch\" data-ch=\"artemida\">Артемиды</span>.)"],["v","Тебя зову, Латои дочь, милей",0,1092,0,0],["v","Для сердца нет тебя, о дева, ты",0,1092,0,0],["v","Моих охот и спутница и радость!",0,1093,0,0],["v","Закрытый нам и славный город отчий",0,1094,0,0],["v","И земли Эрехтея, говорю<a class=\"nr\" href=\"#n-k41\" data-n=\"k41\" aria-label=\"Примечание 41\">41</a>",0,1094,0,0],["v","И вам прости последнее. И ты",0,1095,0,0],["v","Прости, моя Трезенская равнина,",0,1096,0,0],["v","Для юных сил твоя отрадна гладь —",0,1096,0,0],["v","Ее глаза в последний раз ласкают…",0,1097,0,0],["v","Вы, юности товарищи, привет",0,1098,0,0],["v","Скажите мне и проводите друга…",0,1098,0,0],["v","Что бы отец ни говорил, а вам",0,1099,0,0],["v","Уж не найти другого, чище сердцем.",0,1100,0,1],["sd","(Уходит со свитой налево.)"],["scene","Третий музыкальный антракт","s19",4,19],["v","Сначала за сценой плач и вопли.",0,1101,0,0],["sp","Хор"],["str","Строфа I"],["v","Если я в сердце, как боги велики, помыслю,",0,1102,0,0],["v","Муки смолкают и страх;",0,1103,2,0],["v","Но и желание верить в могучую неба поддержку",0,1104,0,0],["v","Тает, когда о делах и о муках раздумаюсь наших.",0,1105,0,0],["v","Вечно — сегодня одно, а завтра другое-",0,1106,2,0],["v","Жребии смертных, что спицы",0,1107,2,0],["v","Быстрых колес, там мелькают.",0,1110,1,1],["str","Антистрофа I"],["v","Я у тебя, о судьба, благодатных даров бы молила,",0,1111,0,0],["v","Чуждое сердце забот.",0,1112,2,0],["v","Я не хотела бы видеть глубокую сущность творений,",0,1113,0,0],["v","Но и в потемках коснеть не хотела бы я суеверных.",0,1114,0,0],["v","Солнце хочу я встречать веселой улыбкой,",0,1115,2,0],["v","Благословляя сегодня",0,1116,2,0],["v","И уповая на завтра.",0,1117,2,0],["str","Строфа II"],["v","Разум мутится, и нет у сердца крылатой надежды:",0,1120,2,1],["v","Эллады звезда золотая",0,1121,2,0],["v","С неба ее на чужие поля закатилась",0,1122,0,0],["v","Гневною волей отца, —",0,1123,2,0],["v","Глади Трезена родного, от вас,",0,1124,0,0],["v","Дикие чащи, от вас,",0,1125,2,0],["v","Где, золотою звездою венчанный,",0,1126,0,0],["v","Царь с <span class=\"ch\" data-ch=\"artemida\">Артемидой</span> за ланью гонялся.",0,1130,2,1],["str","Антистрофа II"],["v","Брызги с копыт и колес взметая, венетские кони",0,1131,2,0],["v","Берегом мчаться не будут;",0,1132,2,0],["v","Залы и портик чертога безмолвны, и струны",0,1133,0,0],["v","Лиры и песни молчат.",0,1134,2,0],["v","Роща богини густая нема,",0,1135,0,0],["v","Дев там увенчанных нет,",0,1136,2,0],["v","Но по тебе не одна, что надежду",0,1140,0,1],["v","В сердце лелеяла, дева вздыхает.",0,1141,2,0],["str","Эпод"],["v","Дни мои слезами мука",0,1142,2,0],["v","Ипполитова наполнит,",0,1143,2,0],["v","Жизнь не в жизнь нам больше будет.",0,1144,2,0],["v","Мать, зачем его носила?",0,1145,2,0],["v","Иль затем, чтоб сердце гневом",0,1146,2,0],["v","Против бога запылало?",0,1147,2,0],["v","Вы ж, три сестры, три Хариты, зачем из отчизны",0,1148,0,0],["v","Нашу безвинную радость из отчего дома берете?",0,1150,0,1],["act","Действие четвертое","a5","IV"],["scene","Явление пятнадцатое","s20",5,20],["sd","С левой стороны приближается вестник — это конюх <span class=\"ch\" data-ch=\"ippolit\">Ипполита</span>."],["sp","Корифей"],["v","Но вижу я из свиты <span class=\"ch\" data-ch=\"ippolit\">Ипполита</span>",0,1151,0,0],["v","Идущего сюда. Как мрачен он!",0,1152,0,0],["sp","Вестник"],["v","Где я царя найду <span class=\"ch\" data-ch=\"tesey\">Тесея</span>, жены?",0,1153,0,0],["v","Скажите мне — он во дворце теперь?",0,1154,0,0],["sp","Корифей"],["v","Он из дворца сейчас сюда выходит.",0,1155,0,0],["v","Из средней двери показывается <span class=\"ch\" data-ch=\"tesey\">Тесей</span> без свиты.",0,1156,0,0],["sp","Вестник"],["v","Тесей, тебе и гражданам твоим,",0,1157,0,0],["v","И в Аттике, и из Трезена вести",0,1158,0,0],["v","Несу. Они должны вас потрясти.",0,1159,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","Какие же? Или одно несчастье",0,1160,0,1],["v","Готовится обоим городам?",0,1160,0,0],["sp","Вестник"],["v","Нет <span class=\"ch\" data-ch=\"ippolit\">Ипполита</span> больше…",0,1161,0,0],["v","Крик ужаса в хоре.",0,1162,0,0],["v","Хоть и видит",1,1162,0,0],["v","Он солнце, но минуты сочтены.",0,1163,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","Как умер он? От мести ли супруга,",0,1164,0,0],["v","Чей дом он, как отцовский, осквернил?",0,1165,0,0],["sp","Вестник"],["v","Его разбили собственные кони, —",0,1166,0,0],["v","Проклятие разбило, что к отцу",0,1167,0,0],["v","Ты обратил, седых морей державцу.",0,1168,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","О, небо! Да, я точно им рожден,",0,1169,0,0],["v","Внимавшим мне из моря Посидоном.",0,1170,0,1],["v","Но как погиб, скажи мне, этот муж,",0,1170,0,0],["v","Поправший честь и пораженный правдой?",0,1171,0,0],["sp","Вестник"],["v","Близ берега, где волны набегают",0,1172,0,0],["v","И плещутся морские, лошадей",0,1173,0,0],["v","Мы чистили и плакали — узнали",0,1174,0,0],["v","Мы от людей, что <span class=\"ch\" data-ch=\"ippolit\">Ипполита</span>, царь,",0,1175,0,0],["v","В изгнанье ты отсюда усылаешь",0,1176,0,0],["v","И здесь уже не жить ему. Пришел",0,1177,0,0],["v","И сам он следом. С нашей песней грустной",0,1178,0,0],["v","Он и свои соединяет слезы.",0,1179,0,0],["v","Без счета их, ровесников, туда",0,1180,0,1],["v","За ним пришло. Тогда, оставив плакать,",0,1180,0,0],["v","Он нам сказал: \"Не надо унывать,",0,1181,0,0],["v","Словам отца повиноваться надо.",0,1182,0,0],["v","Живей, рабы, живее запрягайте:",0,1183,0,0],["v","Трезена нет уж боле для меня\".",0,1184,0,0],["v","И загорелось дело: приказать",0,1185,0,0],["v","Он не успел — уж лошади готовы.",0,1186,0,0],["v","Тут ловко он вскочил на передок",0,1187,0,0],["v","И с ободка схватил проворно вожжи,",0,1188,0,0],["v","Но кобылиц сдержал и, к небесам",0,1189,0,0],["v","Воздевши руки, стал тогда молиться:",0,1190,0,1],["v","\"О Зевс, с клеймом злодея жизни вовсе",0,1190,0,0],["v","Не надо мне. Но дай когда-нибудь,",0,1191,0,0],["v","Останусь я в живых иль не останусь,",0,1192,0,0],["v","Чтобы отец мой понял, как он дурно",0,1192,0,0],["v","Со мною поступил\". Стрекало он",0,1193,0,0],["v","Затем приняв, кобыл поочередно",0,1194,0,0],["v","Касается. Мы ж около вожжей",0,1195,0,0],["v","У самой побежали колесницы,",0,1195,0,0],["v","Чтоб проводить его. А путь ему",0,1196,0,0],["v","Лежал, Тесей, на Аргос, той дорогой,",0,1197,0,0],["v","Которая ведет и на Коринф.",0,1197,0,0],["v","Но вот, когда мы выехали в поле",0,1198,1,0],["v","Пустынное, с которого холмы",0,1199,0,0],["v","К Саронскому спускаются заливу,",0,1200,0,1],["v","Какой-то гул подземный, точно гром,<a class=\"nr\" href=\"#n-k42\" data-n=\"k42\" aria-label=\"Примечание 42\">42</a>",0,1200,0,0],["v","Послышался оттуда отдаленный,",0,1201,0,0],["v","Вселяя страх, и кобылицы вмиг",0,1202,0,0],["v","Насторожились, вытянувши шеи,",0,1203,0,0],["v","А мы вокруг пугливо озирались…",0,1204,0,0],["v","И вот глаза открыли там, где берег",0,1205,0,0],["v","Прибоем волн скалистый убелен,",0,1205,0,0],["v","Огромную волну. Она вздымалась",0,1206,0,0],["v","Горою прямо дивной, постепенно",0,1207,0,0],["v","Застлав от нас Скирона побережье,",0,1208,0,0],["v","И дальний Истм, и даже Эпидавра",0,1209,0,0],["v","От глаз она закрыла скалы. Вот",0,1210,0,1],["v","Еще она раздулась и, сверкая,",0,1210,0,0],["v","Надвинулась и на берег метнулась,",0,1211,0,0],["v","И из нее явилось, на манер",0,1212,0,0],["v","Быка, чудовище. Ущелья следом",0,1213,0,0],["v","Окрестные наполнил дикий рев…",0,1214,0,0],["v","И снова, и ужасней даже будто",0,1215,0,0],["v","Бык заревел. Как выдержать глаза,",0,1216,0,0],["v","Не знаю я, то зрелище сумели?",0,1217,0,0],["v","Мгновенно страх объемлет кобылиц…",0,1218,0,0],["v","Тут опытный возничий, своему",0,1219,0,0],["v","Искусству верный — вожжи намотавши,",0,1220,0,1],["v","Всем корпусом откинулся — гребец",0,1221,0,0],["v","Заносит так весло. Но кобылицы,",0,1222,0,0],["v","Сталь закусив зубами, понесли…",0,1223,0,0],["v","И ни рука возничего, ни дышло",0,1224,0,0],["v","И ни ярмо их бешеных скачков",0,1225,0,0],["v","Остановить уж не могли. Попытку",0,1226,0,0],["v","Последнюю он сделал на песок",0,1227,0,0],["v","Прибрежный их направить. Вдруг у самой",0,1228,0,0],["v","Чудовище явилось колесницы,",0,1229,0,0],["v","И четверня шарахнулась в смятенье",0,1230,0,1],["v","Назад, на скалы. Скачка началась",0,1230,0,0],["v","Безумная. Куда метнутся кони,",0,1231,0,0],["v","Туда и зверь — он больше не ревел,",0,1231,0,0],["v","Лишь надвигался он все ближе, ближе…",0,1232,0,0],["v","Вот наконец отвесная стена…",0,1233,0,0],["v","Прижата колесница. Колесо",0,1233,0,0],["v","Трещит, — и вдребезги… и опрокинут",0,1234,0,0],["v","Царь вместе с колесницей. Это был",0,1235,0,0],["v","Какой-то взрыв. Смешались, закружились",0,1235,0,0],["v","Осей обломки и колес, а царь",0,1236,0,0],["v","Несчастный в узах повлачился тесных",0,1236,0,0],["v","Своих вожжей, — о камни головой",0,1237,0,0],["v","Он бился, и от тела оставались",0,1238,0,0],["v","На остриях камней куски живые.",0,1238,0,0],["v","Тут не своим он голосом кричит:",0,1239,0,0],["v","\"Постойте ж вы, постойте, кобылицы!",0,1240,0,1],["v","Не я ли вас у яслей возрастил?",0,1240,0,0],["v","Постойте же и не губите — это",0,1241,0,0],["v","Проклятие отца. О, неужель",0,1242,0,0],["v","Невинному никто и не поможет?\"",0,1243,0,0],["v","Отказа бы и не было. Да были",0,1243,0,0],["v","Мы далеко. Уж я не знаю, как",0,1244,0,0],["v","Он путы сбил, но мы едва живого",0,1245,0,0],["v","Его нашли на поле. А от зверя",0,1246,0,0],["v","И кобылиц давно простыл и след.",0,1246,0,0],["v","В ущелиях ли, где ль они исчезли,",0,1247,0,0],["v","Ума не приложу.",0,1248,0,0],["v","Хоть я, конечно,",1,1248,0,0],["v","В твоих чертогах царских только конюх,",0,1249,0,0],["v","Но я бы не поверил никогда",0,1250,0,1],["v","Про сына твоего дурному слову,",0,1250,0,0],["v","Пускай бы, сколько есть на свете жен,",0,1251,0,0],["v","Хоть все повесились и писем выше,",0,1252,0,0],["v","Чем Ида, мне наоставляли гору.<a class=\"nr\" href=\"#n-k43\" data-n=\"k43\" aria-label=\"Примечание 43\">43</a>",0,1253,0,0],["v","Я знаю только, царь, что <span class=\"ch\" data-ch=\"ippolit\">Ипполит</span>",0,1253,0,0],["v","Невинен и хороший человек.",0,1254,0,0],["sp","Корифей"],["v","Увы! Увы! Опять удар, и меткий!",0,1255,0,0],["v","Да, от судьбы, как видно, не уйти.",0,1256,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["dir","после некоторого размышления"],["v","Мне пострадавший все же ненавистен,",0,1256,0,0],["v","И сладостны мне были вести мук.",0,1257,0,0],["v","Но я родил его, и узы крови",0,1258,0,0],["v","Священные я помню, потому —",0,1259,0,0],["v","Ни радости, ни горю здесь не место.",0,1260,0,1],["sp","Вестник"],["v","Но как же быть теперь? Оставить там,",0,1260,0,0],["v","Чтоб из твоей нам, царь, не выйти воли?",0,1261,0,0],["v","Коль смею я советовать, не будь",0,1262,0,0],["v","Ты так жесток, владыка, к мукам сына.",0,1262,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","Сюда его несите… Заглянуть",0,1263,0,0],["v","В глаза ему хочу и волей бога",0,1264,0,0],["v","И этой карой страшной уличить",0,1265,0,0],["v","Хочу его во лжи и злодеянье.",0,1265,0,0],["sd","Вестник уходит налево; <span class=\"ch\" data-ch=\"tesey\">Тесей</span> остается на сцене в раздумье."],["sp","Хор"],["v","О Киприда, суровую душу людей",0,1266,0,0],["v","И богов железную волю",0,1267,0,0],["v","Ты, богиня, сгибаешь.",0,1267,0,0],["v","И над черной землею с тобой,",0,1268,0,0],["v","И над влагой соленой и звучной,",0,1269,0,0],["v","Как радуга, яркий Эрот",0,1270,0,1],["v","На быстрых крылах пролетает…",0,1270,0,0],["v","И если он бурный полет",0,1271,0,0],["v","На чье-нибудь сердце направит,",0,1272,0,0],["v","То дикое пламя мгновенно",0,1273,0,0],["v","От золота крыльев",0,1274,0,0],["v","Там вспыхнет любви и безумья,",0,1275,0,0],["v","А чары его",0,1275,0,0],["v","И в чаще, и в волнах таимых",0,1276,0,0],["v","Зверей укрощают и все,",0,1277,0,0],["v","Что дышит в сиянии солнца,",0,1278,0,0],["v","И люди ему",0,1279,0,0],["v","Покорны. Твоя, о Киприда,",0,1280,0,1],["v","Весь мир наполняет держава.",0,1280,0,0],["act","Исход","a6",""],["scene","Явление шестнадцатое","s21",6,21],["v","<span class=\"ch\" data-ch=\"artemida\">Артемида</span> на высоком помосте и <span class=\"ch\" data-ch=\"tesey\">Тесей</span>.",0,1281,0,0],["sp","<span class=\"ch\" data-ch=\"artemida\">Артемида</span>"],["v","Внемли: тебе я говорю,",0,1282,0,0],["v","Сын благородного Эгея,",0,1282,0,0],["v","Тебе, божественная дочь",0,1283,0,0],["v","Латои. Как ты мог, безумный,",0,1284,0,0],["v","Веселье в сердце ощутить?",0,1285,0,0],["v","Я говорю тебе — судом,",0,1285,0,0],["v","Судом неправым ты убил",0,1286,0,0],["v","Тобой рожденного",0,1287,0,0],["v","Жены",1,1287,0,0],["v","Словами ложными окован,",0,1287,0,0],["v","Неясный грех ты обратил",0,1288,0,0],["v","В мир поразившее злодейство…",0,1289,0,0],["v","Потемок Тартара теперь",0,1290,0,1],["v","Желай для своего позора,",0,1290,0,0],["v","Иль птицей сделаться желай,",0,1291,0,0],["v","И ввысь от этой оскверненной",0,1292,0,0],["v","Тобою улететь земли.",0,1293,2,0],["v","Нет больше места для тебя",0,1294,2,0],["v","Средь чистых в этом мире вовсе…",0,1295,2,0],["v","Я свиток зол должна перед тобой",0,1295,0,0],["v","Развить, Тесей, без пользы — лишь печали",0,1296,0,0],["v","Прибавит он, я знаю, но пришла",0,1297,0,0],["v","Я для того, чтоб сын твой честно умер,",0,1298,0,0],["v","Оправданный. И я жены твоей",0,1299,0,0],["v","Любовное должна раскрыть безумье",0,1300,0,1],["v","И, может быть, борьбу. Ее Эрот",0,1300,0,0],["v","Ужалил сердце тайно, и любовью",0,1301,0,0],["v","К царевичу царица запылала:",0,1301,0,0],["v","Богиня так хотела, что для нас,",0,1302,0,0],["v","В невинности отраду находящих,",0,1302,0,0],["v","Особенно бывает ненавистна.",0,1303,0,0],["v","И разумом <span class=\"ch\" data-ch=\"afrodita\">Киприду</span> одолеть",0,1304,0,0],["v","Пыталася царица, но в ловушку",0,1304,0,0],["v","<span class=\"ch\" data-ch=\"kormilitsa\">Кормилицы</span> попалась. Та ее",0,1305,0,0],["v","Царевичу любовь пересказала,",0,1305,0,0],["v","Связав его ужасной клятвой раньше,",0,1306,0,0],["v","Чтоб он молчал. Ее слова твой сын",0,1307,0,0],["v","Отринул, но благочестиво клятвы",0,1307,0,0],["v","Нарушить не дерзнул он, как его",0,1308,0,0],["v","Ни унижал ты здесь. А эту ложь",0,1308,0,0],["v","Оставила царица, умирая,",0,1309,0,0],["v","Боясь улики праведной. А ты,",0,1310,0,1],["v","Ее словам поверив, сына проклял.",0,1310,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","Увы!..",0,1311,0,0],["sp","<span class=\"ch\" data-ch=\"artemida\">Артемида</span>"],["v","Мучительны слова мои, Тесей,",0,1312,0,0],["v","Но должен ты их молча слушать дальше,",0,1313,0,0],["v","И, царь… тебе еще придется плакать…",0,1314,0,0],["v","Ты помнишь ли, о низкий, что тебе",0,1315,0,0],["v","Три выполнить желания поклялся",0,1315,0,0],["v","Отец, но гибель вражью ты презрел —",0,1316,0,0],["v","Одно из них направил против сына…",0,1317,0,0],["v","Не Посидон виновен тут: его",0,1318,0,0],["v","И помыслы, и свято исполненье.",0,1319,0,0],["v","Ты перед ним и ты передо мной",0,1320,0,1],["v","Единственный виновник, потому что",0,1320,0,0],["v","Ты не искал свидетелей, гаданьем",0,1321,0,0],["v","Ты пренебрег, улик не разобрал",0,1322,0,0],["v","И, времени для истины жалея,",0,1323,0,0],["v","С поспешностью преступною своей",0,1323,0,0],["v","Божественным сгубил проклятьем сына.",0,1324,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","О, дай мне умереть…",0,1325,0,0],["sp","<span class=\"ch\" data-ch=\"artemida\">Артемида</span>"],["v","Ты согрешил,",1,1325,0,0],["v","Но и тебе возможно оправданье.",0,1326,0,0],["v","<span class=\"ch\" data-ch=\"afrodita\">Киприды</span> здесь желания и гнев",0,1326,0,0],["v","Слились, <span class=\"ch\" data-ch=\"tesey\">Тесей</span>. А меж богов обычай:",0,1327,0,0],["v","Наперекор друг другу не идти.",0,1328,0,0],["v","Мы в сторону отходим, если бог",0,1329,0,0],["v","Горячие желанья разливает.",0,1330,0,1],["v","О, если бы не страх, что оскорблю",0,1330,0,0],["v","Я Зевса, как хранителя законов,<a class=\"nr\" href=\"#n-k45\" data-n=\"k45\" aria-label=\"Примечание 45\">45</a>",0,1331,0,0],["v","Иль, думаешь, я бы подъяла стыд,",0,1332,0,0],["v","Любимого из смертных уступая",0,1333,0,0],["v","Богам земли? Твоя вина, Тесей,",0,1334,0,0],["v","Неведеньем ослаблена и тем,",0,1335,0,0],["v","Что воли злой ты не имел; с собою",0,1335,0,0],["v","От правды ключ царица унесла,",0,1336,0,0],["v","А смерть ее твой помутила разум…",0,1337,0,0],["v","Всех тяжелей тебе, конечно, царь,",0,1338,0,0],["v","Но скорбь и я с тобой делю. Печалит",0,1339,0,0],["v","И нас людей благочестивых смерть,",0,1340,0,1],["v","И только злых мы с корнем вырвать рады.",0,1341,0,0],["scene","Явление семнадцатое","s22",6,22],["sd","В конце следующих слов корифея слева толпа несет ложе с <span class=\"ch\" data-ch=\"ippolit\">Ипполитом</span>, у которого закрыты глаза. Рабы несут его тяжело и осторожно. Стоны с носилок. Движение в хоре. <span class=\"ch\" data-ch=\"tesey\">Тесей</span> закрыл лицо руками. Светлое облако, осенявшее <span class=\"ch\" data-ch=\"artemida\">Артемиду</span>, померкло."],["v","Ипполит, <span class=\"ch\" data-ch=\"artemida\">Артемида</span> и <span class=\"ch\" data-ch=\"tesey\">Тесей</span>.",0,1342,0,0],["sp","Корифей"],["v","Уж вот он… О, горький… Меж локонов череп,",0,1343,0,0],["v","В обрывках одежды цветущее тело",0,1344,0,0],["v","Разбито, истерзано. Тяжкая доля!",0,1345,0,0],["v","Два траура в доме! Два траура в доме!",0,1346,0,0],["sp","<span class=\"ch\" data-ch=\"ippolit\">Ипполит</span>"],["v","О, смерть…",0,1347,0,0],["v","Из уст нечестивых неправда проклятий…",0,1348,0,0],["v","Что сделал ты с сыном, отец?",0,1349,0,0],["v","О, горе! О, горе, о, смерть!",0,1350,0,1],["v","Мне череп пронзили безумные боли.",0,1351,0,0],["v","В мозгу моем жало — вонзится, и выйдет,",0,1352,0,0],["v","И снова вонзится… Минуту покоя,",0,1353,0,0],["v","Минуту покоя пожертвуй, змея!",0,1354,0,0],["v","Ты, ад колесницы. Не вас ли я сам",0,1355,0,0],["v","И р<em>о</em>стил, и холил давно, кобылицы?..",0,1356,0,0],["v","Вы рвали меня, вы, терзая, убили…",0,1357,0,0],["v","Ох, тише! Богами молю вас, рабы,",0,1358,0,0],["v","Касайтесь нежней до избитого тела:",0,1359,0,0],["v","Я — рана сплошная. Кто справа?",0,1360,0,1],["v","Не вижу. Тихонько берите",0,1360,0,0],["v","И, шаг умеряя, вперед подвигайте",0,1361,0,0],["sd","Рабы снова поднимают ложе и ставят его на левой стороне сцены, ближе к краю."],["v","Забытого небом, кого и отец",0,1362,0,0],["v","В греховном безумии проклял…",0,1363,0,0],["v","О, призри же, Зевс, о, призри с небес,",0,1364,0,0],["v","Богов я всегда почитал — я невинно",0,1365,0,0],["v","И чисто я жил, если кто на земле",0,1365,0,0],["v","Невинно живет. Но в корень моя",0,1366,0,0],["v","Загублена жизнь. И могилы",0,1367,0,0],["v","Я слышу дыханье. И даром",0,1368,0,0],["v","Страдал я и набожен был меж людей.",0,1369,0,0],["v","Ой… ой!",0,1370,3,1],["v","Увы мне… Опять… Эти боли",0,1371,0,0],["v","Впиваются. Жалят.",0,1372,0,0],["v","Оставьте ж меня!",0,1373,0,0],["v","Ты, черная, сжалься, возьми нас",0,1374,0,0],["v","Иль, люди, добейте хоть вы. Нет мочи!",0,1375,0,0],["v","И режущей стали",0,1376,0,0],["v","Удара я жду, точно ласки…",0,1377,0,0],["v","Рабы поднимают носилки, он видит <span class=\"ch\" data-ch=\"tesey\">Тесея</span>.",0,1378,0,0],["v","О, злое проклятье отца!",0,1379,0,0],["v","Запятнанных предков, старинных,",0,1380,0,1],["v","Но крови единой — грехи,<a class=\"nr\" href=\"#n-k47\" data-n=\"k47\" aria-label=\"Примечание 47\">47</a>",0,1380,0,0],["v","Грехи меня губят… возмездье",0,1381,0,0],["v","Растет их, покоя не зная…",0,1382,0,0],["v","Но отчего ж надо мной разразился",0,1383,0,0],["v","Гнев этот старый?",0,1383,0,0],["v","Над чистым, невинным зачем он",0,1384,0,0],["v","Так тешится злобно? Увы мне!",0,1385,0,0],["v","О, что же мне делать? От мук",0,1386,0,0],["v","Страшных куда же укроюсь?",0,1386,0,0],["sd","Пауза."],["v","Ты, черная сила Аида, несчастного тихой,",0,1387,0,0],["v","Тихой дремотой обвей.",0,1388,0,0],["sd","Пауза. На помосте загорается облако: <span class=\"ch\" data-ch=\"artemida\">Артемида</span>. <span class=\"ch\" data-ch=\"ippolit\">Ипполит</span> ее не видит."],["sp","<span class=\"ch\" data-ch=\"artemida\">Артемида</span>"],["v","О, сколько мук, о муж, великим сердцем",0,1389,0,0],["v","Загубленный, я вижу над тобой…",0,1390,0,1],["sp","<span class=\"ch\" data-ch=\"ippolit\">Ипполит</span>"],["v","А…",0,1390,0,0],["v","Волшебное благоуханье! В муках",0,1391,0,0],["v","Ты льешься в грудь… и будто легче мне…",0,1392,0,0],["v","Ты здесь со мной, со мною, Артемида?",0,1393,0,0],["sp","<span class=\"ch\" data-ch=\"artemida\">Артемида</span>"],["v","Она с тобой, любимый, бедный друг.",0,1394,0,0],["sp","<span class=\"ch\" data-ch=\"ippolit\">Ипполит</span>"],["v","Владычица, ты видишь <span class=\"ch\" data-ch=\"ippolit\">Ипполита</span>?",0,1395,0,0],["sp","<span class=\"ch\" data-ch=\"artemida\">Артемида</span>"],["v","Из смертных глаз бы слезы полились.",0,1396,0,0],["sp","<span class=\"ch\" data-ch=\"ippolit\">Ипполит</span>"],["v","Товарищ твой и спутник умирает.",0,1397,0,0],["sp","<span class=\"ch\" data-ch=\"artemida\">Артемида</span>"],["v","Но он умрет в лучах моей любви.",0,1398,0,0],["sp","<span class=\"ch\" data-ch=\"ippolit\">Ипполит</span>"],["v","Возница твой… твоих лугов хранитель.",0,1399,0,0],["sp","<span class=\"ch\" data-ch=\"artemida\">Артемида</span>"],["v","<span class=\"ch\" data-ch=\"afrodita\">Кипридою</span> коварной унесен.",0,1400,0,1],["sp","<span class=\"ch\" data-ch=\"ippolit\">Ипполит</span>"],["v","О, я познал ее в дыханье смерти.",0,1400,0,0],["sp","<span class=\"ch\" data-ch=\"artemida\">Артемида</span>"],["v","Простить тебе богиня не могла",0,1401,0,0],["v","Ни чистоты, ни алтарей забвенья.",0,1402,0,0],["sp","<span class=\"ch\" data-ch=\"ippolit\">Ипполит</span>"],["v","Теперь мне все понятно: не одну,",0,1403,0,0],["v","А целых три взяла <span class=\"ch\" data-ch=\"afrodita\">Киприда</span> жертвы.",0,1404,0,0],["sp","<span class=\"ch\" data-ch=\"artemida\">Артемида</span>"],["v","Ты, твой отец и <span class=\"ch\" data-ch=\"fedra\">Федра</span>, целых три.",0,1405,0,0],["sp","<span class=\"ch\" data-ch=\"ippolit\">Ипполит</span>"],["v","Да, и отца судьба достойна плача.",0,1405,0,0],["sp","<span class=\"ch\" data-ch=\"artemida\">Артемида</span>"],["v","Его коварно демон обманул.",0,1406,0,0],["sp","<span class=\"ch\" data-ch=\"ippolit\">Ипполит</span>"],["dir","смотря на <span class=\"ch\" data-ch=\"tesey\">Тесея</span>"],["v","Твое, отец, жестоко испытанье.",0,1407,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","Жестоко так, что адом стал и свет.",0,1408,0,0],["sp","<span class=\"ch\" data-ch=\"ippolit\">Ипполит</span>"],["v","Тебе больней, чем мне, твоя ошибка.",0,1409,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","О, если бы тебя мне заменить…",0,1410,0,1],["sp","<span class=\"ch\" data-ch=\"ippolit\">Ипполит</span>"],["v","То горький был подарок Посидона.",0,1410,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","Когда бы мог вернуть его <span class=\"ch\" data-ch=\"tesey\">Тесей</span>.",0,1411,0,0],["sp","<span class=\"ch\" data-ch=\"ippolit\">Ипполит</span>"],["v","Тогда бы гнев его со мной покончил…",0,1412,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","Затмение, ужасный дар богов…",0,1413,0,0],["sp","<span class=\"ch\" data-ch=\"ippolit\">Ипполит</span>"],["v","Увы! Увы!",0,1414,0,0],["v","Их наши-то проклятья не достигнут…",0,1415,0,0],["sp","<span class=\"ch\" data-ch=\"artemida\">Артемида</span>"],["v","Оставь богов. Иль думаешь, что гнев,",0,1416,0,0],["v","Который до могильной ночи сердце",0,1417,0,0],["v","Великое и чистое терзал,",0,1418,0,0],["v","Останется неотомщенным? Я…",0,1419,0,0],["v","Я отомщу одной из стрел моих,",0,1420,0,1],["v","Которые не вылетают даром…",0,1420,0,0],["v","Меж смертными стрела моя найдет,",0,1421,0,0],["v","Кто ей милей других. Тебя же, бедный,",0,1422,0,0],["v","О лучший друг, в Трезене отличу",0,1423,0,0],["v","Я честию высокой. Перед свадьбой",0,1424,0,0],["v","Пусть каждая девица дар волос",0,1425,0,0],["v","Тебе несет. И этот в даль немую",0,1426,0,0],["v","Обычай перейдет веков. И в вечность",0,1427,0,0],["v","Сам в пении девичьих чистых уст",0,1428,0,0],["v","Ты перейдешь. И как тебя любила,",0,1429,0,0],["v","Не позабудут, Федра… Царь <span class=\"ch\" data-ch=\"tesey\">Тесей</span>,",0,1430,0,1],["v","Поди сюда, и сына обоими,",0,1430,0,0],["v","И поцелуй его. Чужою волей",0,1431,0,0],["v","Ты умертвил его. И дивно ль вам",0,1432,0,0],["v","Грешить, когда того желают боги?..",0,1433,0,0],["v","Ты ж, Ипполит, я и тебя прошу",0,1434,0,0],["v","Гнев на отца оставить. Ведь таков",0,1435,0,0],["v","Был твой удел. Простимся. Взор небесный",0,1435,0,0],["v","Не должен видеть смерти, и глаза",0,1436,0,0],["v","Туманит нам холодное дыханье.",0,1437,0,0],["v","А черная уж над тобой… я вижу…",0,1438,0,0],["v","<span class=\"ch\" data-ch=\"tesey\">Тесей</span> обнимает сына молча.",0,1439,0,0],["sp","<span class=\"ch\" data-ch=\"ippolit\">Ипполит</span>"],["v","Будь счастлива, блаженная, и ты",0,1440,0,1],["v","Там, в голубом эфире… Ты любила",0,1415,0,0],["v","Меня и долго, но легко оставишь…",0,1389,0,0],["v","Отцу, как ты велела, я простил…<a class=\"nr\" href=\"#n-k46\" data-n=\"k46\" aria-label=\"Примечание 46\">46</a>",0,1363,0,0],["v","Я слов твоих не преступал и раньше.",0,1337,0,0],["v","<span class=\"ch\" data-ch=\"artemida\">Артемида</span> исчезает.",0,1311,0,0],["scene","Явление восемнадцатое","s23",6,23],["sd","Без <span class=\"ch\" data-ch=\"artemida\">Артемиды</span>."],["sp","<span class=\"ch\" data-ch=\"ippolit\">Ипполит</span>"],["v","Но на глаза спадает мрак. Отец,<a class=\"nr\" href=\"#n-k44\" data-n=\"k44\" aria-label=\"Примечание 44\">44</a>",0,1285,0,0],["v","Возьми меня, приподними немного.",0,1260,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","Дитя мое! Не добивай отца.",0,1234,0,0],["sp","<span class=\"ch\" data-ch=\"ippolit\">Ипполит</span>"],["v","Смерть!.. Вот они, подземные ворота!",0,1208,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","Под бременем злодейства не покинь.",0,1182,0,0],["sp","<span class=\"ch\" data-ch=\"ippolit\">Ипполит</span>"],["v","О, я тебя, отец, освобождаю…",0,1156,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","Как? этот груз с меня снимаешь? весь?..",0,1130,0,1],["sp","<span class=\"ch\" data-ch=\"ippolit\">Ипполит</span>"],["v","Да, девственной клянусь я <span class=\"ch\" data-ch=\"artemida\">Артемидой</span>.",0,1131,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","О лучший сын! О благородный сын!",0,1132,0,0],["sp","<span class=\"ch\" data-ch=\"ippolit\">Ипполит</span>"],["v","Дай бог таких тебе, отец, законных.",0,1455,0,1],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","И потерять такое сердце… О…",0,1454,0,1],["sp","<span class=\"ch\" data-ch=\"ippolit\">Ипполит</span>"],["v","Прощай, отец… Прости меня, мой милый.",0,1453,0,1],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","Ты выдержишь… Ты одолеешь смерть.",0,1456,0,1],["sp","<span class=\"ch\" data-ch=\"ippolit\">Ипполит</span>"],["dir","тихо"],["v","Я выдержал… я уж в объятьях смерти.",0,1456,0,0],["v","Отец… скорее пеплос на лицо…",0,1457,0,0],["v","<span class=\"ch\" data-ch=\"tesey\">Тесей</span> прикрывает агонию.",0,1458,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","О, славные афинские пределы,",0,1459,0,0],["v","И ты, Пелопоннес! Кого сейчас",0,1460,0,1],["v","Лишитесь вы… А мне, увы! <span class=\"ch\" data-ch=\"afrodita\">Киприда</span>",0,1461,0,0],["v","Страдания оставила клеймо.",0,1462,0,0],["sd","Пауза. <span class=\"ch\" data-ch=\"tesey\">Тесей</span> снимает с мертвого пеплос. Все глубоко склоняются перед телом. Минута молчания."],["sp","Хор"],["dir","удаляется под мерные звуки анапестов"],["v","Этот траур двойной и нежданный…",0,1463,0,0],["v","Лейтесь слезы под веслами скорби,",0,1464,0,0],["v","И далеко, далеко звучи",0,1465,0,0],["v","Весть о горе великом царей!",0,1466,0,0],["h1","Комментарий","comm"],["p","Трагедия поставлена в 428 г. до н. э. и принесла поэту первую премию. Античные источники часто пользуются для обозначения этой трагедии названием «Ипполит, несущий венок» (ср. ст. 73 сл.), чтобы отличить ее от более ранней, не сохранившейся трагедии Еврипида «Ипполит, закрывающийся плащом». Там действие происходило в Афинах в то время, когда Тесей отправился в подземное царство, и Федра сама признавалась Ипполиту, ища сближения с ним. Такое откровенное изображение женской страсти, очевидно, шокировало афинских зрителей, и трагедия провалилась, но именно этот характер разработки сюжета привлек внимание римских поэтов — Сенеки (трагедия «Федра») и Овидия («Послания героинь», 4). Среди аттических драматургов трагедию о Федре написал Софокл; из нее сохранились, однако, незначительные отрывки, и ни время ее создания, ни тематическое соотношение с трагедиями Еврипида неизвестно."],["p","Разработка мифа о Федре и Ипполите до V в. не засвидетельствована, и поздняя античность знает его лишь в той форме, какую придала ему аттическая трагедия. Несомненно, однако, что афинские драматурги в своей трактовке мифа могли опереться на некоторые родственные сказания и данные культа. Федра, согласно мифу, была дочерью критского царя Миноса и Пасифаи, известной своим преступным союзом с быком, от которого она родила чудовище Минотавра — получеловека-полубыка (см. ст. 337 сл.). В основе своей этот миф уводит в отдаленнейшие времена зооморфизма, когда боги представлялись в облике животных, покровительствующих данному племени, и с точки зрения историка религии соединение Пасифаи с быком является ничуть не более «безнравственным», чем похищение Европы Зевсом в образе быка или его явление Леде под видом лебедя. В классическую эпоху, когда перестали понимать первоначальный смысл мифа, за Пасифаей и ее дочерьми укрепилась репутация порочных женщин, склонных к нарушению естественных связей (ср. ст. 337-343). Что касается Ипполита, то по своему происхождению он являлся местным божеством или обожествленным героем, о судьбе которого сообщалось в ритуальных девичьих хорах в Трезене; перед замужеством трезенские девушки приносили ему в жертву пряди волос (ст. 1423-1429). Таким образом, связь Ипполита с культами Артемиды, покровительницы девственниц, и Афродиты, под чью власть переходят девушки, вступая в брак, является достаточно древней, переосмысление же этого образа скорее всего принадлежит целиком Еврипиду."],["p","Перевод Анненского в «Театре Еврипида» сопровождался посвящением Ф. Ф. Зелинскому."],["ed","В.Н. Ярхо"],["note","k1"],["note","k2"],["note","k3"],["note","k4"],["note","k5"],["note","k6"],["note","k7"],["note","k8"],["note","k9"],["note","k10"],["note","k11"],["note","k12"],["note","k13"],["note","k14"],["note","k15"],["note","k16"],["note","k17"],["note","k18"],["note","k19"],["note","k20"],["note","k21"],["note","k22"],["note","k23"],["note","k24"],["note","k25"],["note","k26"],["note","k27"],["note","k28"],["note","k29"],["note","k30"],["note","k31"],["note","k32"],["note","k33"],["note","k34"],["note","k35"],["note","k36"],["note","k37"],["note","k38"],["note","k39"],["note","k40"],["note","k41"],["note","k42"],["note","k43"],["note","k44"],["note","k45"],["note","k46"],["note","k47"]],"n":{"k1":["Ст. 10-12. Трезен","город в Арголиде, где некогда царствовал Питфей, тесть Тесея. Ему Тесей отдал на воспитание своего сына Ипполита, родившегося от брака с амазонкой Антиопой (известны и другие имена матери Ипполита; Еврипид удовлетворяется тем, что называет ее просто амазонкой). Сюда же, в Трезен, Тесей вынужден был удалиться на год из Афин, убив в схватке некоторых из своих родственников Паллантидов (см. ст. 35), т. е. сыновей своего дяди Палланта, пытавшихся лишить его афинского престола. Согласно Плутарху («Тесей», гл. 13) Тесей совершил это убийство в юные годы, еще не будучи отцом Ипполита и тем более мужем Федры, которую он взял в жены только после смерти своей первой супруги, амазонки. Еврипид, перенося действие своей трагедии из Афин в Трезен, должен был пойти на смещение мифологической хронологии."],"k2":["Ст. 25. …чтоб Элевсина таинства узреть…","Первую встречу Федры с Ипполитом Еврипид приурочивает к моменту, когда юноша направился в Афины для посвящения в Элевсинские мистерии — религиозное действо, издавна совершавшееся в поселении Элевсин, недалеко от Афин, и со временем приобретшее общегосударственное значение. Афиняне считали, что эти таинства были установлены самой богиней Деметрой."],"k3":["Ст. 29-33","Стихи, вызывающие большие трудности в их истолковании. В Афинах, на южном склоне Акрополя, находилась «гробница Ипполита», а невдалеке от нее — святилище Афродиты, которое в одной аттической надписи носит название «Афродиты около Ипполита». Основание этого святилища молва могла приписывать Федре; трудно, однако, поверить, чтобы Федра из дошедшей трагедии, всячески скрывающая свое чувство, решилась на открытое посвящение Афродите храма, названного запретным именем. Следует, наконец, помнить, что основание храма у могилы Ипполита было бы в такой ситуации преждевременным. Иначе могли развертываться события в недошедшем «Ипполите», где Федра, вероятно, оклеветала Ипполита, отнюдь не помышляя о своей смерти, и, только узнав о последствиях клеветы, приняла решение уйти из жизни; в этот момент Федра как раз могла завещать кому-либо из близких основать храм, хранящий память о всемогуществе Афродиты, над могилой Ипполита. Поэтому возможно, что ст. 29-33 попали в текст нашей трагедии из «Ипполита, закрывающегося плащом»."],"k4":["Ст. 45","Посейдон был божественным отцом Тесея, как Зевс — Геракла."],"k5":["Ст. 61-72","Охотники составляют дополнительный хор, подобно хору афинских граждан, провожающих к месту их вечного поселения Эриний в финале «Орестеи» Эсхила."],"k6":["Ст. 79-82","Точный перевод: «Лишь тот, кто обрел целомудрие, а равно и все остальное, не от учения, а от природы, вправе срывать эти цветы, дурные же не вправе». «Целомудрие» (sophrosyne) — многозначное слово: кроме этого буквального значения, оно означает и «здравомыслие», «чувство меры» (одну из четырех главных добродетелей), и, расширительно, «добродетель» вообще. Это отклик на споры софистов о том, научима ли добродетель."],"k7":["Ст. 136. …от Деметры дивной брашна…","Федра отказывается от пищи (брашна), дара Деметры."],"k8":["Ст. 141-144. Пан","См. примеч. к «Медее», ст. 1171. Геката — Во власти этой богини, связанной с ночными обрядами, находились привидения и ночные кошмары. Корибанты — шумные спутники великой богини Реи-Кибелы, сопровождавшие обряды в ее честь оргиастической пляской. Диктинна — одно из имен Артемиды. <br class=\"xb\"><span class=\"xn\"><i class=\"xa\">↳</i> <b>«Медея», Ст. 1171. Пан.</b> божество, вселявшее в человека, по представлениям греков, внезапный, безотчетный страх.</span><!--/xn-->"],"k9":["Ст. 176-266","Первая сцена кормилицы и Федры выдержана в оригинале в анапестических диметрах (четырехстопные анапесты), чередующихся с монометрами (две стопы), и делится на три части, каждая из которых завершается усеченным стихом (ст. 197, 238, 266). Это редкое для диалогической сцены построение передано в переводе только отчасти."],"k10":["Ст. 231. …четверню… венетскую…","Венеты (племя, проживавшее на иллирийском побережье Адриатического моря) славились своими конями. В Греции венетские кони стали впервые известны после 440 г., когда спартанец Леон одержал на них победу в состязаниях колесниц."],"k11":["Ст. 308. …детям… твоим…","Сыновьями Федры были Демофонт и Акамант; см. «Гераклиды», ст. 119."],"k12":["Ст. 310","Как видно, кормилица вспоминает Ипполита совсем не в той связи, в какой он занимает мысли Федры. Но, будучи названо, его имя дает толчок дальнейшему диалогу, и важность этого подчеркивается редким разделением стиха (в оригинале) натри реплики (см. примеч. к «Алькесте», ст. 1119). <br class=\"xb\"><span class=\"xn\"><i class=\"xa\">↳</i> <b>«Алькеста», Ст. 1119.</b> Стих разделен на три реплики, как и ст. 391. Там Адмет терял Алькесту, здесь вновь ее обретает.</span><!--/xn-->"],"k13":["Ст. 352","Снова важное признание Федры разделено на две реплики (ср. ст. 310)."],"k14":["Ст. 374","…преддверия Пелоповой державы… — Трезен был преддверием Пелопоннеса с точки зрения афинян, которые могли легко добраться до него на корабле через Саронический залив, вместо того чтобы совершать длительное сухопутное путешествие через Мегариду, Коринфский перешеек и гористую северную Арголиду."],"k15":["Ст. 427. …с желаньем жить…","Неточный перевод: в оригинале нет ни слова ни о желании жить, ни тем более о совести (см. примеч. к «Медее», ст. 1054). Смысл подлинника: «Говорят, что только одно может соперничать в ценности (или в длительности) с жизнью человека — это его благородный и справедливый образ мыслей». <br class=\"xb\"><span class=\"xn\"><i class=\"xa\">↳</i> <b>«Медея», Ст. 1054. …совесть… не позволяет….</b> В оригинале речь идет не о совести (это понятие только появляется в V в. и встречается у Еврипида еще редко), а о тех, «кому не подобает присутствовать» при этом жертвоприношении.</span><!--/xn-->"],"k16":["Ст. 471. Ты","женщина… — Неверный перевод. В оригинале Еврипид говорит о том, что всякий человек должен считать себя счастливым, если в нем больше хорошего, чем дурного."],"k17":["Ст. 486-489. О, злая лесть…","Перевод, очень далекий от оригинала. В подлиннике Федра высказывает гораздо более общую мысль: «Вот что губит у людей хорошо управляемые государства и семьи — чересчур красивые речи. Между тем говорить следует не приятное для ушей, а такое, из чего возникает добрая слава»."],"k18":["Ст. 490","и сл. Кормилица уже здесь готова выступить в роли сводни, но, встретив отчаянный отпор Федры (ст. 498 сл., 503-506, ср. 518-520), занимает двусмысленную позицию: ее слова о средстве от недуга (ст. 509-512) Федра понимает так, что кормилица может излечить ее от любви, и этим объясняется ее вполне деловой вопрос в ст. 516. Но отсюда ясно, что ст. 513-515 (но не плошай] разрушают всю двойную игру кормилицы и могут быть объяснены только как поздняя и неумелая вставка в текст оригинала."],"k19":["Ст. 534. Дим","Зевс; однако происхождение Эрота от Зевса представляет совершенно необычный вариант мифологической генеалогии."],"k20":["Ст. 535. Алфей","река в Элиде; на ее правом берегу находился город Олимпия со знаменитым храмом Зевса. Пифийские храмы — святилища в Дельфах. Бычьи туши — гекатомбы, когда приносилось в жертву целое стадо быков."],"k21":["Ст. 545 — 554","Ярма не познавшая дева… — Иола, дочь эхалийского царя Еврита. Чтобы овладеть ею, Геракл захватил и разорил Эхалию и убил Еврита. Однако пленение Иолы послужило причиной мучительной смерти самого Геракла (см. «Трахинянки» Софокла)."],"k22":["Ст. 556. Диркея (правильнее Дирка)","источник вблизи Фив."],"k23":["Ст. 560. Грядущую Вакхову матерь","Семелу."],"k24":["Ст. 569-596","Небольшой коммос, т. е. совместная лирическая партия актера и хора, перемежаемая репликами актера. Симметричные строфы расположены здесь в зеркальном порядке, т. е. abc = cba; ритмическая симметрия оригинала в переводе выдержана недостаточно точно. Стих «Мне ж она дала…» — добавление переводчика."],"k25":["Ст. 635","Здесь Анненский пропустил несколько строк, считавшихся подложными. Ф. Ф. Зелинский переводит их так:<br>А раз женился — не стряхнуть ему<br>Ярма. Один, свойством польщенный знатным,<br>Выносит ложе пресное; другой,<br>Шурьев постыдных за своей красоткой<br>В родню впустив, полынью приправляет<br>Медвяную сыту. И хорошо<br>Еще тому, кому попалось в дом…"],"k26":["Ст. 722 сл","В оригинале реплики корифея и Федры звучат проще; корифей спрашивает: «Какое же ты хочешь совершить неисправимое зло?» На это Федра отвечает: «Умереть. А как — я еще обдумаю»."],"k27":["Ст. 732-751","В первой паре строф хор называет фантастические страны, куда бы он хотел укрыться от тягостей окружающей его действительности. Эридан — мифическая река, отождествляемая с Роной или По; в нее, по преданию, рухнул Фаэтон, сраженный молнией Зевса; его сестры («.Несчастные девы»}, превратившись в тополя, оплакивают его янтарными слезами. Сады Гесперид греки локализовали на Крайнем Западе, в районе нынешнего Гибралтара: здесь узкий пролив преграждает путь кораблям по воле морей промыслителя — Посейдона, здесь Атлант — мученик небодержавный — несет на плечах небесный свод, здесь бьет источник амбросии — пищи богов, и здесь же находилось ложе Кронида, когда он впервые соединился с Герой."],"k28":["Ст. 752-765","Хор вспоминает о брачном путешествии Федры и Тесея с Крита в афинскую гавань Мунихий, видя в сопровождавших этот акт мрачных приметах предвестников свершающихся бедствий."],"k29":["Ст. 776-786","В некоторых рукописях вопли за сценой приписывают служанке Федры: кормилица после суровой отповеди Федры в ст. 708 сл. удалилась во дворец и не смела подходить близко к спальне своей госпожи. Большого значения вопрос о принадлежности этих реплик не имеет."],"k30":["Ст. 792. …царя, узревшего святыню…","В отличие от недошедшего «Ипполита», где отсутствие Тесея объяснялось его походом в загробное царство, в нашей трагедии Тесей возвращается как паломник из святыни какого-то бога. Поэтому на голове у него венок из свежей листвы (ст. 806 ел.), в переводе Анненского — из лавра."],"k31":["Ст. 817-833",", 836-851. В оригинале строфы Тесея построены на чередовании лирических двустиший с декламационными (ямбическими триметрами); в переводе эта особенность не передана."],"k32":["Ст. 866-870","Эту партию хора многие исследователи считают вставкой, попавшей в рукописи нашей трагедии из несохранившегося «Ипполита»: хотя хор может подозревать о каком-то новом несчастье, грозящем дому Тесея (ср. ст. 871-873), его отчаянье в разбираемой партии явно преждевременно."],"k33":["Ст. 871-873","отсутствовали в древнейших рукописях и опущены Анненским. Ф. Ф. Зелинский переводит их:<br>О боже! Если есть еще возможность,<br>Услышь мою молитву: не губи нас.<br>Недоброе душа мне ворожит."],"k34":["Ст. 901. Набожным желаньем","добавка переводчика. В оригинале сказано: «Прими решение, самое лучшее для твоего дома»."],"k35":["Ст. 952-954. …Орфеевым снабдил ты ярлыком.","Тесей приписывает Ипполиту приверженность к учению орфиков, которые верили в переселение душ и потому проповедовали вегетарианство. Это обвинение, однако, не очень вяжется с обликом Ипполита-охотника."],"k36":["Ст. 977-980. Синис","разбойник, живший на Истме (Коринфском перешейке); попавших ему в руки путников он привязывал к вершинам двух сосен и, отпустив затем деревья, разрывал людей пополам. Скирон — разбойник, обитавший на скале на границе Мегариды и Коринфа (см. «Гераклиды», ст. 859 сл.); он заставлял путников мыть ему ноги и во время этой процедуры сталкивал их со скалы в море. Оба были убиты Тесеем, когда он в юности шел из Трезена в Афины искать своего отца Эгея."],"k37":["Ст. 1045-1050. Казни… не жди.","Эти слова, по-видимому, противоречат желанию Тесея, высказанному в обращении к Посейдону (ст. 887-890). Объяснить это противоречие можно с разных точек зрения: 1) либо Тесей не хочет раскрывать перед Ипполитом своего замысла, чтобы заставить его пережить сначала весь ужас изгнания; 2) либо Еврипид здесь, как и ранее (ст. 893-898), воспроизводит мотив из какого-нибудь другого варианта мифа, где Тесей ограничивался изгнанием Ипполита."],"k38":["Ст. 1053-1054. …за гранью Атлантовой…","То есть за пределами Земли. См. примеч. к ст. 732-751. <br class=\"xb\"><span class=\"xn\"><i class=\"xa\">↳</i> <b>Ст. 732-751.</b> В первой паре строф хор называет фантастические страны, куда бы он хотел укрыться от тягостей окружающей его действительности. Эридан — мифическая река, отождествляемая с Роной или По; в нее, по преданию, рухнул Фаэтон, сраженный молнией Зевса; его сестры («.Несчастные девы»}, превратившись в тополя, оплакивают его янтарными слезами. Сады Гесперид греки локализовали на Крайнем Западе, в районе нынешнего Гибралтара: здесь узкий пролив преграждает путь кораблям по воле морей промыслителя — Посейдона, здесь Атлант — мученик небодержавный — несет на плечах небесный свод, здесь бьет источник амбросии — пищи богов, и здесь же находилось ложе Кронида, когда он впервые соединился с Герой.</span><!--/xn-->"],"k39":["Ст. 1058","…птицы, в небесах… — По полету птиц специальные гадатели определяли будущее и угодность богам того или иного решения смертных."],"k40":["Ст. 1082. О, горькое рожденье, внебрачное!","Жалоба, хорошо понятная в современных Еврипиду Афинах, но лишенная смысла в «героические» времена."],"k41":["Ст. 1095. Земли Эрехтея","Афины, названные так по имени легендарного царя Эрехтея. См. примеч. к «Медее», ст. 824-845. <br class=\"xb\"><span class=\"xn\"><i class=\"xa\">↳</i> <b>«Медея», Ст. 824-845.</b> Пара строф, прославляющих Афины. Эрехтиды — афиняне, возводившие свой род к легендарному царю Эрехтею. Пиэриды — Музы, родившиеся, по традиционному варианту мифа, в Пиэрии (область в Северной Греции) от Зевса и Мнемосины. Еврипид же называет их родиной Аттику, а матерью — Гармонию. Кефис — река в Аттике.</span><!--/xn-->"],"k42":["Ст. 1197-1200","В описании маршрута Ипполита Еврипид приносит географическую точность в жертву художественному эффекту: дорога из Трезена на север и северо-запад (в Эпидавр, Коринф, Аргос) проходит среди гор, а не вдоль моря; по берегу Трезен отрезан от Эпидавра стеной скал."],"k43":["Ст. 1253","Поскольку Федра родом с Крита, вестник имеет в виду гору Иду на этом острове, а не одноименную горную цепь в Троаде."],"k44":["Ст. 1282-1295","Вступительная речь Артемиды выдержана в оригинале в анапестах. В ст. 1282 и 1169 сл. с древнегреческой точки зрения нет противоречия: Эгей считался земным отцом Тесея, Посейдон — его божественным родителем."],"k45":["Ст. 1331 сл","Перевод значительно усиливает мысль оригинала, где сказано только: «Если бы я не боялась Зевса». Артемида хочет сказать, что, поскольку у богов установлен закон не вмешиваться в дела друг друга, нарушение ею этого правила могло бы вызвать недовольство Зевса — мысль, нигде больше не встречающаяся. В эпосе, где боги поступают целиком по собственному усмотрению, гнев Зевса грозит им только в том случае, если они осмеливаются нарушать его собственные планы."],"k46":["Ст. 1342-1369","в оригинале выдержаны в анапестических диметрах, с 1370 начинается монодия Ипполита."],"k47":["Ст. 1380 сл. Запятнанных предков… грехи.","Ипполит, как и Тесей в ст. 820, 831 сл., видит причину бедствий, обрушившихся на невиновных, в каких-то преступлениях предков, за которые теперь мстит божество."]},"mainEnd":2215,"c":[{"id":"ippolit","name":"Ипполит","role":"Сын Тесея и амазонки, почитатель Артемиды","intro":"Юноша-охотник, чистый и гордый, отвергающий Афродиту.","arc":"Ипполит гибнет от своей добродетели, доведённой до гордыни: он чтит одну Артемиду и презирает Киприду, и богиня решает его наказать. Его гнев на кормилицу и монолог против женщин показывают ту же непримиримость. При этом он верен клятве молчания даже ценой жизни. Перед смертью Артемида открывает правду, и Ипполит прощает отца — это единственный миг примирения в трагедии.","st":[{"i":193,"p":9,"l":"Пролог · явление второе","t":"Отказ почтить Киприду","d":"Возвращается с охоты, приносит венок Артемиде; на совет старого раба почтить и Афродиту отвечает холодным презрением.","c":"Его участь уже решена в прологе.","k":false},{"i":1052,"p":48,"l":"Действие второе · явление седьмое","t":"Негодование","d":"Узнав от кормилицы о любви Федры, в ярости проклинает весь женский род, но обещает молчать, связанный клятвой.","c":"Он сохраняет клятву — и этим губит себя.","k":true},{"i":1683,"p":76,"l":"Действие третье · явление тринадцатое","t":"Обвинённый отцом","d":"Тесей обвиняет его по письму Федры. Ипполит клянётся в невиновности, но правды не открывает.","c":"Верность клятве против правды.","k":false},{"i":1704,"p":77,"l":"Действие третье · явление четырнадцатое","t":"Изгнание","d":"Прощается с Трезеном и друзьями и уезжает.","c":"","k":false},{"i":1931,"p":87,"l":"Действие четвертое · явление пятнадцатое","t":"Бык из моря","d":"Вестник рассказывает: Посейдон наслал чудовищного быка, кони понесли, и Ипполита разбило о скалы.","c":"Проклятие отца исполнилось.","k":false},{"i":2214,"p":100,"l":"Исход · явление восемнадцатое","t":"Прощение отца","d":"Принесённый умирающим, слышит Артемиду и снимает с отца вину за свою смерть.","c":"Последний жест — милосердие.","k":true}],"gen":"Ипполит"},{"id":"fedra","name":"Федра","role":"Жена Тесея, дочь Миноса","intro":"Царица, которую Афродита поразила страстью к пасынку.","arc":"Еврипидова Федра благородна и стыдлива: она решила уморить себя голодом, лишь бы не выдать позорной страсти. Её тайну вырывает кормилица, и всё дальнейшее происходит против её воли. Услышав гнев Ипполита, она боится позора и уходит из жизни, оставив письмо-клевету: так она спасает честь детей и мстит гордецу.","st":[{"i":844,"p":38,"l":"Действие первое · явление пятое","t":"Признание","d":"Изнурённая, в бреду мечтает об охоте и лесах. Под мольбами кормилицы называет имя Ипполита. Говорит о том, как боролась со страстью.","c":"Тайна выпущена из рук.","k":true},{"i":1121,"p":51,"l":"Действие второе · явление восьмое","t":"Позор раскрыт","d":"Слышит, как Ипполит бранит кормилицу, и проклинает её за предательство.","c":"Опасается, что Ипполит всё расскажет отцу.","k":false},{"i":1159,"p":52,"l":"Действие второе · явление девятое","t":"Решение","d":"Объявляет хору, что умрёт, но так, чтобы и Ипполит понял, что такое смирение.","c":"Самоубийство и посмертная месть.","k":true},{"i":1409,"p":64,"l":"Действие третье · Сцена плача","t":"Письмо","d":"Тесей находит на руке мёртвой табличку: Федра обвиняет Ипполита в насилии.","c":"","k":false}],"gen":"Федра"},{"id":"kormilitsa","name":"Кормилица","role":"Старая няня Федры","intro":"Преданная и практичная старуха, готовая на всё ради госпожи.","arc":"Кормилица — голос житейской морали: «боги тоже любят», страсть лучше утолить, чем умереть. Желая спасти Федру, она открывает её тайну Ипполиту и тем губит её.","st":[{"i":844,"p":38,"l":"Действие первое · явление пятое","t":"Выпытывает тайну","d":"Узнав, что Федра любит пасынка, сначала в ужасе, затем уговаривает уступить страсти.","c":"Из утешительницы становится сводней.","k":true},{"i":1052,"p":48,"l":"Действие второе · явление седьмое","t":"Разговор с Ипполитом","d":"Связав юношу клятвой, открывает ему всё — и вызывает взрыв негодования.","c":"","k":false},{"i":1121,"p":51,"l":"Действие второе · явление восьмое","t":"Отвергнута","d":"Федра проклинает её; кормилица признаёт ошибку, но обещает «найти средство».","c":"","k":false}]},{"id":"tesey","name":"Тесей","role":"Царь Афин и Трезена","intro":"Муж Федры и отец Ипполита, возвращающийся из паломничества.","arc":"Тесей скор на гнев: не дождавшись доказательств, он проклинает сына одним из трёх даров Посейдона и изгоняет его. Его трагедия — в позднем знании: от Артемиды он узнаёт, что сын невиновен.","st":[{"i":1409,"p":64,"l":"Действие третье · Сцена плача","t":"Проклятие","d":"Найдя письмо Федры, призывает Посейдона погубить сына.","c":"Решение, которое уже нельзя отменить.","k":true},{"i":1683,"p":76,"l":"Действие третье · явление тринадцатое","t":"Изгнание сына","d":"Не верит клятвам Ипполита, обличает его лицемерие и изгоняет.","c":"","k":false},{"i":2020,"p":91,"l":"Исход · явление шестнадцатое","t":"Правда от Артемиды","d":"Богиня открывает ему, что он погубил невинного.","c":"Гнев сменяется раскаянием.","k":false},{"i":2214,"p":100,"l":"Исход · явление восемнадцатое","t":"Прощён сыном","d":"Умирающий Ипполит освобождает отца от вины.","c":"","k":false}],"gen":"Тесей"},{"id":"afrodita","name":"Афродита","role":"Богиня любви","intro":"Богиня, мстящая Ипполиту за пренебрежение.","arc":"Афродита открывает трагедию и сама объявляет её план: Федра погибнет, но лишь как средство наказать Ипполита.","st":[{"i":91,"p":4,"l":"Пролог · явление первое","t":"Пролог","d":"Объявляет, что накажет Ипполита за презрение; Федра станет орудием её мести.","c":"","k":true}],"gen":"Афродита"},{"id":"artemida","name":"Артемида","role":"Богиня-охотница","intro":"Покровительница Ипполита.","arc":"Артемида является в конце, когда уже ничего нельзя исправить: она открывает Тесею правду и обещает Ипполиту посмертные почести.","st":[{"i":2020,"p":91,"l":"Исход · явление шестнадцатое","t":"Правда","d":"Разоблачает перед Тесеем обман Федры.","c":"","k":false},{"i":2214,"p":100,"l":"Исход · явление восемнадцатое","t":"Прощание с Ипполитом","d":"Обещает ему культ в Трезене и месть Афродите; уходит, не желая видеть смерть.","c":"","k":true}]}]};
